const CAREER_FLUENCY_BOOK={"id":"career-fluency","title":"English Communication & Career Fluency","level":"A2+ → B1","module":1,"moduleTitle":"Fluency Foundations","moduleGoal":"Build automatic speaking habits, natural conversation control and clear professional self-expression.","lessons":[{"id":"w1l1","number":1,"week":1,"title":"Your starting point","outcome":"Complete a friendly speaking diagnostic and identify one clear fluency goal.","expressions":[{"text":"Let me think for a moment.","job":"gain thinking time without becoming silent","cloze":"___ me think for a moment.","answer":"Let","choices":["Let","Make","Give"]},{"text":"What I mean is…","job":"restate an idea more clearly","cloze":"What I ___ is…","answer":"mean","choices":["mean","say","tell"]},{"text":"Could you repeat the question?","job":"ask to hear a question again","cloze":"Could you ___ the question?","answer":"repeat","choices":["repeat","return","reply"]},{"text":"In my experience…","job":"connect an answer to real life","cloze":"In my ___…","answer":"experience","choices":["experience","example","opinion"]},{"text":"One goal I have is…","job":"state a learning or career goal","cloze":"One ___ I have is…","answer":"goal","choices":["goal","job","reason"]}],"grammar":{"focus":"Complete simple sentences, question forms, and infinitives for goals.","items":[{"q":"Choose the complete sentence.","options":["I use English at work.","I English at work.","Use English work."],"answer":"I use English at work.","tag":"grammar:complete-sentence"},{"q":"Choose the accurate question.","options":["Where do you use English?","Where you use English?","Where does you use English?"],"answer":"Where do you use English?","tag":"grammar:question-form"},{"q":"Choose the accurate goal sentence.","options":["I want to speak more confidently.","I want speak more confidently.","I want speaking more confidently."],"answer":"I want to speak more confidently.","tag":"grammar:infinitive"},{"q":"Choose the correct sentence.","options":["I feel confident when I read.","I feels confident when I read.","I feeling confident when I read."],"answer":"I feel confident when I read.","tag":"grammar:present-simple"},{"q":"Complete: One thing I ___ well is reading.","options":["do","does","doing"],"answer":"do","tag":"grammar:do"},{"q":"Choose the correct negative.","options":["I do not use English every day.","I not use English every day.","I does not use English every day."],"answer":"I do not use English every day.","tag":"grammar:negative"},{"q":"Choose the best question for a goal.","options":["What would you like to improve?","What you would like improve?","What would like you improve?"],"answer":"What would you like to improve?","tag":"grammar:question-order"},{"q":"Complete: My main difficulty ___ speaking quickly.","options":["is","are","be"],"answer":"is","tag":"grammar:be"},{"q":"Choose the accurate time phrase.","options":["In twelve weeks, I want to improve.","At twelve weeks, I want improve.","On twelve weeks, I improving."],"answer":"In twelve weeks, I want to improve.","tag":"grammar:time-phrase"},{"q":"Choose the best combined sentence.","options":["I can read well, but spontaneous speaking is harder.","I can read well, because spontaneous speaking is harder.","I can read well, so spontaneous speaking is harder."],"answer":"I can read well, but spontaneous speaking is harder.","tag":"grammar:connector"}]},"listening":{"title":"My English starting point","questions":[{"q":"What is the speaker mainly describing?","options":["Their current English ability and one goal","A holiday plan","A new job offer"],"answer":"Their current English ability and one goal","tag":"listening:main-idea"},{"q":"Where does the speaker use English at work?","options":["Reading messages and speaking with colleagues","Only writing essays","Only answering phone calls"],"answer":"Reading messages and speaking with colleagues","tag":"listening:detail"},{"q":"What does the speaker do online?","options":["Watches videos and searches for information","Teaches a class","Buys airline tickets"],"answer":"Watches videos and searches for information","tag":"listening:detail"},{"q":"Which skill feels comfortable?","options":["Reading","Spontaneous speaking","Giving presentations"],"answer":"Reading","tag":"listening:detail"},{"q":"What happens when the speaker must answer quickly?","options":["They sometimes pause too long","They always change the topic","They speak much faster"],"answer":"They sometimes pause too long","tag":"listening:detail"},{"q":"Why does the speaker pause?","options":["They are searching for the right word","They are bored","They cannot hear the question"],"answer":"They are searching for the right word","tag":"listening:inference"},{"q":"When does the speaker communicate better?","options":["When they have a few seconds to think","When they read a full script","When they avoid questions"],"answer":"When they have a few seconds to think","tag":"listening:detail"},{"q":"What is the twelve-week speaking goal?","options":["Speak for two minutes with fewer stops","Write a ten-page report","Learn one hundred grammar rules"],"answer":"Speak for two minutes with fewer stops","tag":"listening:goal"},{"q":"What strategy does the speaker want to use confidently?","options":["Ask for repetition","Avoid difficult questions","Translate every sentence"],"answer":"Ask for repetition","tag":"listening:strategy"},{"q":"Which phrase best summarizes the message?","options":["Know your starting point, then set a measurable goal.","Perfect grammar must come first.","Only reading matters for fluency."],"answer":"Know your starting point, then set a measurable goal.","tag":"listening:inference"}]},"writing":{"tasks":[{"prompt":"Write one sentence about where you use English.","minWords":5},{"prompt":"Write one sentence about a skill you already do well.","minWords":5},{"prompt":"Write one sentence about a speaking situation that feels difficult.","minWords":5},{"prompt":"Write a complete question you could ask a teacher about your English.","minWords":5},{"prompt":"Use “In my experience…” in a true sentence.","minWords":5},{"prompt":"Use “One goal I have is…” to state a measurable goal.","minWords":8},{"prompt":"Explain why that goal matters to you in 2–3 sentences.","minWords":15},{"prompt":"Describe one situation where you need English and what usually happens.","minWords":20},{"prompt":"Draft stage: Write a short 40–60 word self-diagnostic: strength, difficulty, and strategy.","minWords":40},{"prompt":"Final rewrite and transfer: write a 70–90 word starting-point profile that you can use to prepare your two-minute baseline.","minWords":70}]},"review":{"keywords":"use · strength · difficulty · goal","mission":"Speak for two minutes about who you are, how you use English, and what you want to achieve in twelve weeks."}},{"id":"w1l2","number":2,"week":1,"title":"A strong professional introduction","outcome":"Introduce yourself with a clear beginning, useful details and a forward-looking ending.","expressions":[{"text":"I currently work as…","job":"state your present role","cloze":"I ___ work as…","answer":"currently","choices":["currently","current","currency"]},{"text":"My background is in…","job":"describe education or professional field","cloze":"My ___ is in…","answer":"background","choices":["background","back","history"]},{"text":"I’m responsible for…","job":"explain a main duty","cloze":"I’m ___ for…","answer":"responsible","choices":["responsible","response","responsibility"]},{"text":"I’m particularly interested in…","job":"name a professional interest","cloze":"I’m ___ interested in…","answer":"particularly","choices":["particularly","particular","partly"]},{"text":"My current goal is to…","job":"finish with a future direction","cloze":"My ___ goal is to…","answer":"current","choices":["current","currently","career"]}],"grammar":{"focus":"Present simple with be, have and work; gerunds after “responsible for”; because for reasons.","items":[{"q":"Choose the accurate role sentence.","options":["I currently work as a project assistant.","I currently works as a project assistant.","I am currently work as a project assistant."],"answer":"I currently work as a project assistant.","tag":"grammar:present-simple"},{"q":"Choose the correct background sentence.","options":["My background is in education.","My background are in education.","My background in is education."],"answer":"My background is in education.","tag":"grammar:be"},{"q":"Choose the correct responsibility sentence.","options":["I’m responsible for preparing reports.","I’m responsible to prepare reports.","I responsible for preparing reports."],"answer":"I’m responsible for preparing reports.","tag":"grammar:gerund"},{"q":"Choose the best reason.","options":["I enjoy my role because I solve problems.","I enjoy my role because of I solve problems.","I enjoy my role because solve problems."],"answer":"I enjoy my role because I solve problems.","tag":"grammar:because"},{"q":"Complete: I ___ two main responsibilities.","options":["have","has","having"],"answer":"have","tag":"grammar:have"},{"q":"Choose the correct subject-verb agreement.","options":["She works with international clients.","She work with international clients.","She working with international clients."],"answer":"She works with international clients.","tag":"grammar:third-person"},{"q":"Complete: My current goal is ___ lead a larger team.","options":["to","for","at"],"answer":"to","tag":"grammar:infinitive"},{"q":"Choose the natural sentence.","options":["I’m particularly interested in digital education.","I particularly interested digital education.","I’m particular interest in digital education."],"answer":"I’m particularly interested in digital education.","tag":"grammar:collocation"},{"q":"Choose the correct question.","options":["What are you responsible for?","What you are responsible for?","What do responsible you for?"],"answer":"What are you responsible for?","tag":"grammar:question-form"},{"q":"Choose the best ending.","options":["My current goal is to improve my leadership skills.","My current goal improve leadership skills.","My current goal is improving to leadership skills."],"answer":"My current goal is to improve my leadership skills.","tag":"grammar:infinitive"}]},"listening":{"title":"A professional introduction","questions":[{"q":"What is Hassan’s current role?","options":["Project assistant","Site supervisor","English teacher"],"answer":"Project assistant","tag":"listening:detail"},{"q":"What is his professional background?","options":["Construction planning","Medicine","Accounting"],"answer":"Construction planning","tag":"listening:detail"},{"q":"How long has he worked with the team?","options":["Almost two years","Ten years","Two months"],"answer":"Almost two years","tag":"listening:detail"},{"q":"Which task is one of his responsibilities?","options":["Preparing weekly updates","Teaching mathematics","Selling construction materials"],"answer":"Preparing weekly updates","tag":"listening:detail"},{"q":"Why is he interested in planning?","options":["He likes turning complicated projects into clear steps","He wants to avoid teamwork","He dislikes project information"],"answer":"He likes turning complicated projects into clear steps","tag":"listening:reason"},{"q":"Who does he work closely with?","options":["Engineers and site supervisors","Only customers","School teachers"],"answer":"Engineers and site supervisors","tag":"listening:detail"},{"q":"Why is communication important in his role?","options":["He works with different project colleagues","He never shares information","He works alone"],"answer":"He works with different project colleagues","tag":"listening:inference"},{"q":"What is his future career goal?","options":["Lead larger projects","Leave construction immediately","Study medicine"],"answer":"Lead larger projects","tag":"listening:goal"},{"q":"What English ability does he want to improve?","options":["Communicate confidently and explain project information clearly","Read only fiction","Memorize grammar terminology"],"answer":"Communicate confidently and explain project information clearly","tag":"listening:detail"},{"q":"Which order best matches the introduction?","options":["Role → background → responsibilities → interest → goal","Goal → hobby → family → role","Problem → apology → goodbye"],"answer":"Role → background → responsibilities → interest → goal","tag":"listening:sequence"}]},"writing":{"tasks":[{"prompt":"Write your current role or study status in one complete sentence.","minWords":5},{"prompt":"Write one sentence beginning “My background is in…”","minWords":5},{"prompt":"Write one responsibility using “I’m responsible for…”","minWords":5},{"prompt":"Write one sentence about a professional interest.","minWords":5},{"prompt":"Write one sentence about your current career goal.","minWords":5},{"prompt":"Add a reason using “because”.","minWords":8},{"prompt":"Write 2–3 sentences explaining your role to a new colleague.","minWords":18},{"prompt":"Write a short introduction that includes role, background and responsibility.","minWords":30},{"prompt":"Draft stage: Add your professional interest and future goal to make a 50–70 word introduction.","minWords":50},{"prompt":"Final rewrite and transfer: write an 80–100 word professional introduction with a clear beginning, development and forward-looking ending.","minWords":80}]},"review":{"keywords":"role · background · responsibility · interest · goal","mission":"Deliver a 90-second professional introduction without reading full sentences."}},{"id":"w1l3","number":3,"week":1,"title":"Keep speaking without long pauses","outcome":"Use thinking phrases, connectors and repair strategies to maintain your turn.","expressions":[{"text":"There are two main reasons.","job":"organise an answer before giving details","cloze":"There are two main ___.","answer":"reasons","choices":["reasons","results","examples"]},{"text":"The first point is…","job":"start your first idea","cloze":"The first ___ is…","answer":"point","choices":["point","place","part"]},{"text":"Another thing is…","job":"add a second idea","cloze":"Another ___ is…","answer":"thing","choices":["thing","reasoning","exampled"]},{"text":"For example…","job":"support an idea with evidence","cloze":"For ___…","answer":"example","choices":["example","reason","case"]},{"text":"Let me say that another way.","job":"repair an unclear sentence","cloze":"Let me say that another ___.","answer":"way","choices":["way","word","time"]}],"grammar":{"focus":"Join ideas with and, but, because and so; organise two-point answers.","items":[{"q":"Choose the best connector: I use English at work ___ I speak with international clients.","options":["because","but","so"],"answer":"because","tag":"grammar:connector-because"},{"q":"Choose the best connector: I understand the topic, ___ I sometimes need more time to answer.","options":["but","because","so"],"answer":"but","tag":"grammar:connector-but"},{"q":"Choose the best connector: I want to work internationally, ___ I practise English every day.","options":["so","but","because"],"answer":"so","tag":"grammar:connector-so"},{"q":"Choose the sentence that adds information.","options":["I read articles and I watch videos.","I read articles but I watch videos because.","I read articles so but videos."],"answer":"I read articles and I watch videos.","tag":"grammar:connector-and"},{"q":"Choose the best organised opening.","options":["There are two main reasons.","Because two reasons are.","Two main there reasons."],"answer":"There are two main reasons.","tag":"grammar:organisation"},{"q":"Complete: The first point ___ communication at work.","options":["is","are","be"],"answer":"is","tag":"grammar:be"},{"q":"Choose the best example sentence.","options":["For example, I speak with international visitors.","For example because I speak international visitors.","Example for I speak visitors."],"answer":"For example, I speak with international visitors.","tag":"grammar:example"},{"q":"Choose the best repair.","options":["Let me say that another way.","Let me saying another way.","Let me to say another way."],"answer":"Let me say that another way.","tag":"grammar:repair-phrase"},{"q":"Choose the strongest two-point structure.","options":["The first point is confidence. Another thing is career growth.","First confidence another career.","The point first because career another."],"answer":"The first point is confidence. Another thing is career growth.","tag":"grammar:organisation"},{"q":"Choose the correctly linked sentence.","options":["English is difficult sometimes, but I keep practising because it matters to my career.","English difficult but because career so.","English is difficult because but I practise."],"answer":"English is difficult sometimes, but I keep practising because it matters to my career.","tag":"grammar:connectors"}]},"listening":{"title":"Why English matters to me","questions":[{"q":"How many main reasons does the speaker give?","options":["Two","Three","One"],"answer":"Two","tag":"listening:main-idea"},{"q":"What is the first reason?","options":["Communication at work","Travel for holidays","Reading novels"],"answer":"Communication at work","tag":"listening:sequence"},{"q":"Who does the speaker sometimes meet?","options":["People from different countries","Only family members","Only classmates"],"answer":"People from different countries","tag":"listening:detail"},{"q":"What example does the speaker give?","options":["Speaking with a visitor about a project schedule","Writing a school exam","Buying a new phone"],"answer":"Speaking with a visitor about a project schedule","tag":"listening:detail"},{"q":"What problem happened during that conversation?","options":["The speaker paused too often","The visitor left immediately","The speaker forgot the project"],"answer":"The speaker paused too often","tag":"listening:detail"},{"q":"What is the second reason?","options":["Career growth","Better handwriting","More free time"],"answer":"Career growth","tag":"listening:sequence"},{"q":"Which opportunities are mentioned?","options":["Training, interviews and more responsibility","Driving lessons and sports","Cooking and shopping"],"answer":"Training, interviews and more responsibility","tag":"listening:detail"},{"q":"What does “Let me say that another way” signal?","options":["The speaker is repairing or clarifying an idea","The speaker is ending the conversation","The speaker is asking a question"],"answer":"The speaker is repairing or clarifying an idea","tag":"listening:strategy"},{"q":"What does the speaker say they do NOT need before speaking?","options":["Perfect English","Useful language","Practice"],"answer":"Perfect English","tag":"listening:inference"},{"q":"What practice strategy does the speaker prefer?","options":["Short answers, examples and repair phrases","Long memorized scripts only","Avoiding difficult topics"],"answer":"Short answers, examples and repair phrases","tag":"listening:strategy"}]},"writing":{"tasks":[{"prompt":"Write one reason English matters to you.","minWords":5},{"prompt":"Add a second reason using “Another thing is…”","minWords":5},{"prompt":"Write one example beginning “For example…”","minWords":5},{"prompt":"Join two ideas with “and”.","minWords":5},{"prompt":"Join two contrasting ideas with “but”.","minWords":5},{"prompt":"Explain one reason using “because”.","minWords":8},{"prompt":"Write a 3-sentence answer with two reasons and one example.","minWords":20},{"prompt":"Write a repair sentence using “Let me say that another way.”","minWords":10},{"prompt":"Draft stage: Write a 50–70 word answer to “Why are you learning English now?”","minWords":50},{"prompt":"Final rewrite and transfer: write an 80–100 word two-point response that you could later deliver as a two-minute talk.","minWords":80}]},"review":{"keywords":"reason 1 · example · reason 2 · repair","mission":"Speak for two minutes: “Why I am learning English now.” Repeat with fewer pauses."}},{"id":"w2l4","number":4,"week":2,"title":"Start conversations naturally","outcome":"Open a conversation in social and professional situations.","expressions":[{"text":"How has your day been so far?","job":"open a relaxed conversation","cloze":"How has your ___ been so far?","answer":"day","choices":["day","work","time"]},{"text":"What brings you here?","job":"ask about purpose at an event","cloze":"What ___ you here?","answer":"brings","choices":["brings","takes","makes"]},{"text":"Have we met before?","job":"check whether you know someone","cloze":"Have we ___ before?","answer":"met","choices":["met","meet","meeting"]},{"text":"How do you know the team?","job":"find a shared connection","cloze":"How do you ___ the team?","answer":"know","choices":["know","knows","knowing"]},{"text":"That sounds interesting.","job":"respond positively before another question","cloze":"That ___ interesting.","answer":"sounds","choices":["sounds","hears","listens"]}],"grammar":{"focus":"Wh- questions, present simple question order, and present perfect for “Have we met…?”","items":[{"q":"Choose the correct opener.","options":["What brings you here?","What you brings here?","What does brings you here?"],"answer":"What brings you here?","tag":"grammar:wh-question"},{"q":"Choose the correct question.","options":["How do you know the team?","How you know the team?","How does you know team?"],"answer":"How do you know the team?","tag":"grammar:question-order"},{"q":"Choose the correct present perfect question.","options":["Have we met before?","Did we met before?","Have we meet before?"],"answer":"Have we met before?","tag":"grammar:present-perfect"},{"q":"Complete: How ___ your day been so far?","options":["has","have","do"],"answer":"has","tag":"grammar:auxiliary"},{"q":"Choose the natural response.","options":["That sounds interesting.","That sound interesting.","That is sound interesting."],"answer":"That sounds interesting.","tag":"grammar:third-person"},{"q":"Choose the safe professional question.","options":["What brings you to this workshop?","How much money do you earn?","Why are you still single?"],"answer":"What brings you to this workshop?","tag":"grammar:appropriacy"},{"q":"Choose the correct present simple question.","options":["Where do you work?","Where you work?","Where does you work?"],"answer":"Where do you work?","tag":"grammar:present-simple-question"},{"q":"Complete: How ___ you know the organiser?","options":["do","are","have"],"answer":"do","tag":"grammar:auxiliary"},{"q":"Choose the best follow-up.","options":["What kind of work do you do?","What kind work you do?","What work does you do?"],"answer":"What kind of work do you do?","tag":"grammar:question-order"},{"q":"Choose the correct sentence.","options":["I’m attending the workshop today.","I attending workshop today.","I am attend the workshop today."],"answer":"I’m attending the workshop today.","tag":"grammar:present-continuous"}]},"listening":{"title":"Meeting someone at a workshop","questions":[{"q":"Where does the conversation happen?","options":["At a digital skills workshop","At a hospital","At a football match"],"answer":"At a digital skills workshop","tag":"listening:setting"},{"q":"What is the first question the woman asks?","options":["Have we met before?","Where do you live?","How old are you?"],"answer":"Have we met before?","tag":"listening:sequence"},{"q":"Why is the speaker at the workshop?","options":["To learn more about technology at work","To buy a phone","To meet a doctor"],"answer":"To learn more about technology at work","tag":"listening:detail"},{"q":"How does the woman react?","options":["That sounds interesting.","That is impossible.","I do not care."],"answer":"That sounds interesting.","tag":"listening:detail"},{"q":"What does she ask next?","options":["How the speaker knows the organising team","How much the speaker earns","Where the speaker was born"],"answer":"How the speaker knows the organising team","tag":"listening:detail"},{"q":"Why do the questions feel natural?","options":["They connect to the event and are not too personal","They are very private","They change topics quickly"],"answer":"They connect to the event and are not too personal","tag":"listening:inference"},{"q":"What does the speaker later ask about?","options":["The woman’s work","Her salary","Her family problems"],"answer":"The woman’s work","tag":"listening:detail"},{"q":"What shared connection do they discover?","options":["Someone from the same community project","The same school teacher","The same house"],"answer":"Someone from the same community project","tag":"listening:detail"},{"q":"What helps the conversation continue?","options":["Each question creates a shared topic","They both read from a script","They avoid asking questions"],"answer":"Each question creates a shared topic","tag":"listening:inference"},{"q":"What is the main lesson?","options":["Use safe, connected opening questions.","Ask personal questions first.","Speak without listening."],"answer":"Use safe, connected opening questions.","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write one safe opening question for a workshop.","minWords":5},{"prompt":"Write one safe opening question for an online meeting.","minWords":5},{"prompt":"Write a friendly response to someone’s answer.","minWords":5},{"prompt":"Write a question beginning “What brings you…”","minWords":5},{"prompt":"Write a question beginning “How do you know…”","minWords":5},{"prompt":"Write a two-line opening exchange.","minWords":10},{"prompt":"Write three connected questions for meeting a new colleague.","minWords":18},{"prompt":"Explain why one personal question might be inappropriate in a professional setting.","minWords":20},{"prompt":"Draft stage: Write a 50–70 word mini-conversation that starts naturally and reaches a shared topic.","minWords":50},{"prompt":"Final rewrite and transfer: write three different conversation openings for three situations: workshop, office reception and online meeting.","minWords":70}]},"review":{"keywords":"opening · safe question · shared topic · follow-up","mission":"Start three different two-minute conversations without using the same opening twice."}},{"id":"w2l5","number":5,"week":2,"title":"Show interest and ask follow-ups","outcome":"Keep a conversation going by responding, echoing and asking connected questions.","expressions":[{"text":"Really? What happened next?","job":"invite someone to continue a story","cloze":"Really? What happened ___?","answer":"next","choices":["next","later","after"]},{"text":"How did you get interested in that?","job":"ask about the origin of an interest","cloze":"How did you get ___ in that?","answer":"interested","choices":["interested","interesting","interest"]},{"text":"What was that like?","job":"ask about an experience","cloze":"What was that ___?","answer":"like","choices":["like","look","feel"]},{"text":"So, you mean that…?","job":"check your understanding","cloze":"So, you ___ that…?","answer":"mean","choices":["mean","means","meaning"]},{"text":"I can relate to that.","job":"connect the speaker’s experience to yours","cloze":"I can ___ to that.","answer":"relate","choices":["relate","relationship","relative"]}],"grammar":{"focus":"Follow-up questions with how, why, when and what happened next.","items":[{"q":"Choose the correct follow-up.","options":["How did you get interested in that?","How you got interested in that?","How did you got interested?"],"answer":"How did you get interested in that?","tag":"grammar:past-question"},{"q":"Choose the correct question.","options":["What was that like?","What that was like?","What did that like?"],"answer":"What was that like?","tag":"grammar:be-question"},{"q":"Choose the natural story follow-up.","options":["What happened next?","What next happened did?","What did happened next?"],"answer":"What happened next?","tag":"grammar:past-question"},{"q":"Complete: Why ___ you choose that course?","options":["did","do","were"],"answer":"did","tag":"grammar:auxiliary"},{"q":"Choose the correct time question.","options":["When did you start?","When you did start?","When did you started?"],"answer":"When did you start?","tag":"grammar:past-question"},{"q":"Choose the checking phrase.","options":["So, you mean that the first week was difficult?","So, you means the first week difficult?","So, mean you first week?"],"answer":"So, you mean that the first week was difficult?","tag":"grammar:checking"},{"q":"Choose the best connected question after “I started a new job.”","options":["How did your first week go?","What is your favorite fruit?","Where is the airport?"],"answer":"How did your first week go?","tag":"grammar:cohesion"},{"q":"Complete: I can ___ to that.","options":["relate","related","relating"],"answer":"relate","tag":"grammar:modal"},{"q":"Choose the correct follow-up after a past event.","options":["How did you feel about it?","How do you felt about it?","How did you felt about it?"],"answer":"How did you feel about it?","tag":"grammar:past-question"},{"q":"Choose the best question form.","options":["What made you decide to continue?","What did made you decide continue?","What make you decided?"],"answer":"What made you decide to continue?","tag":"grammar:question-form"}]},"listening":{"title":"Keeping a story going","questions":[{"q":"What new skill is the colleague learning?","options":["Mapping software","Cooking","Driving"],"answer":"Mapping software","tag":"listening:detail"},{"q":"What does the speaker do first to show interest?","options":["Says “Really?” and asks a connected question","Changes the topic","Talks only about themselves"],"answer":"Says “Really?” and asks a connected question","tag":"listening:strategy"},{"q":"Who introduced the colleague to mapping?","options":["A colleague","A family member","A teacher at school"],"answer":"A colleague","tag":"listening:detail"},{"q":"What can mapping help with?","options":["Community projects","Cooking dinner","Learning music"],"answer":"Community projects","tag":"listening:detail"},{"q":"How were the first lessons?","options":["Challenging","Very easy","Boring and useless"],"answer":"Challenging","tag":"listening:detail"},{"q":"Why did she continue?","options":["She enjoyed seeing progress","She was forced to","She wanted to stop immediately"],"answer":"She enjoyed seeing progress","tag":"listening:inference"},{"q":"What does the speaker check?","options":["Whether practice made the difficult beginning easier","Whether she bought a new computer","Whether she changed jobs"],"answer":"Whether practice made the difficult beginning easier","tag":"listening:checking"},{"q":"How does the speaker relate personally?","options":["By mentioning learning a reporting system","By changing to travel","By talking about salary"],"answer":"By mentioning learning a reporting system","tag":"listening:detail"},{"q":"What do all the questions have in common?","options":["They connect to the previous answer","They are unrelated","They are yes/no only"],"answer":"They connect to the previous answer","tag":"listening:inference"},{"q":"What is the main communication skill?","options":["Show interest and ask connected follow-ups","Give a formal presentation","End a conversation quickly"],"answer":"Show interest and ask connected follow-ups","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write a natural reaction to “I started a new course.”","minWords":5},{"prompt":"Write one follow-up beginning “How did…”","minWords":5},{"prompt":"Write one follow-up beginning “What was…”","minWords":5},{"prompt":"Write one checking question beginning “So, you mean…”","minWords":5},{"prompt":"Write one sentence using “I can relate to that.”","minWords":5},{"prompt":"Write two connected follow-up questions about learning a skill.","minWords":12},{"prompt":"Write a 4-line conversation where every question connects to the previous answer.","minWords":25},{"prompt":"Explain the difference between a connected follow-up and a sudden topic change.","minWords":25},{"prompt":"Draft stage: Write a 60–80 word conversation about learning something difficult.","minWords":60},{"prompt":"Final rewrite and transfer: create a six-exchange conversation using at least three target follow-up expressions.","minWords":80}]},"review":{"keywords":"story · reaction · follow-up · checking","mission":"Keep one conversation going for six exchanges using at least three follow-up expressions."}},{"id":"w2l6","number":6,"week":2,"title":"End conversations professionally","outcome":"Close conversations warmly, confirm next steps and leave a positive final impression.","expressions":[{"text":"It was great speaking with you.","job":"signal a warm ending","cloze":"It was great ___ with you.","answer":"speaking","choices":["speaking","speak","spoke"]},{"text":"I should let you get back to…","job":"respect the other person’s time","cloze":"I should let you get ___ to…","answer":"back","choices":["back","return","again"]},{"text":"Let’s stay in touch.","job":"suggest future contact","cloze":"Let’s stay in ___.","answer":"touch","choices":["touch","contacting","talk"]},{"text":"I’ll send you the details.","job":"promise a next action","cloze":"I’ll ___ you the details.","answer":"send","choices":["send","sent","sending"]},{"text":"I look forward to speaking again.","job":"close a professional interaction","cloze":"I look ___ to speaking again.","answer":"forward","choices":["forward","ahead","future"]}],"grammar":{"focus":"Future arrangements with will and present continuous; “look forward to” + -ing.","items":[{"q":"Choose the correct promise.","options":["I’ll send you the details this afternoon.","I send you details tomorrow yesterday.","I’ll sending the details."],"answer":"I’ll send you the details this afternoon.","tag":"grammar:will"},{"q":"Choose the correct arrangement.","options":["I’m meeting the team tomorrow.","I meeting the team tomorrow.","I’m meet the team tomorrow."],"answer":"I’m meeting the team tomorrow.","tag":"grammar:present-continuous"},{"q":"Choose the correct phrase.","options":["I look forward to speaking again.","I look forward to speak again.","I look forward speaking again."],"answer":"I look forward to speaking again.","tag":"grammar:gerund"},{"q":"Complete: It ___ great speaking with you.","options":["was","were","be"],"answer":"was","tag":"grammar:be"},{"q":"Complete: Let’s ___ in touch.","options":["stay","staying","stayed"],"answer":"stay","tag":"grammar:let-us"},{"q":"Choose the polite time signal.","options":["I should let you get back to the workshop.","You need go now.","Stop talking now."],"answer":"I should let you get back to the workshop.","tag":"grammar:appropriacy"},{"q":"Choose the correct next step.","options":["I’ll review it tomorrow.","I’ll reviewed it tomorrow.","I review it tomorrow yesterday."],"answer":"I’ll review it tomorrow.","tag":"grammar:will"},{"q":"Choose the correct future question.","options":["When will you send the link?","When you will send the link?","When will you sent the link?"],"answer":"When will you send the link?","tag":"grammar:future-question"},{"q":"Complete: We’re ___ again on Thursday.","options":["meeting","meet","met"],"answer":"meeting","tag":"grammar:present-continuous"},{"q":"Choose the strongest professional close.","options":["It was great speaking with you. I’ll send the details today.","Bye. Maybe something later.","Okay finished."],"answer":"It was great speaking with you. I’ll send the details today.","tag":"grammar:cohesion"}]},"listening":{"title":"Closing a professional conversation","questions":[{"q":"What signal tells the speaker it may be time to end?","options":["The other person looks toward the next session","The lights turn off","Someone starts eating"],"answer":"The other person looks toward the next session","tag":"listening:inference"},{"q":"What polite time signal does the speaker use?","options":["I should let you get back to the workshop.","You must leave now.","I am bored."],"answer":"I should let you get back to the workshop.","tag":"listening:strategy"},{"q":"How does the other person describe the conversation?","options":["Great speaking with you","Too long and difficult","Not useful"],"answer":"Great speaking with you","tag":"listening:detail"},{"q":"What does the speaker suggest?","options":["Stay in touch","Never speak again","Change the workshop"],"answer":"Stay in touch","tag":"listening:detail"},{"q":"What does the speaker promise to send?","options":["A project link","A new laptop","A job contract"],"answer":"A project link","tag":"listening:detail"},{"q":"When will it be sent?","options":["That afternoon","Next month","The previous day"],"answer":"That afternoon","tag":"listening:detail"},{"q":"When will the other person review it?","options":["The next day","Immediately before receiving it","Next year"],"answer":"The next day","tag":"listening:sequence"},{"q":"Why is the next step useful?","options":["It makes the follow-up clear","It makes the ending longer","It avoids all future contact"],"answer":"It makes the follow-up clear","tag":"listening:inference"},{"q":"What final phrase does the speaker use?","options":["I look forward to speaking again.","Do not contact me.","That is all."],"answer":"I look forward to speaking again.","tag":"listening:detail"},{"q":"What makes the ending professional?","options":["Respecting time, confirming a next step, and closing warmly","Leaving without saying anything","Making several vague promises"],"answer":"Respecting time, confirming a next step, and closing warmly","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write one warm closing sentence.","minWords":5},{"prompt":"Write one sentence that respects the other person’s time.","minWords":5},{"prompt":"Write one next-action promise using “I’ll…”","minWords":5},{"prompt":"Write one future arrangement using present continuous.","minWords":5},{"prompt":"Write one sentence using “I look forward to…” correctly.","minWords":5},{"prompt":"Write a two-line professional closing.","minWords":12},{"prompt":"Write a closing that includes a specific deadline for your next action.","minWords":15},{"prompt":"Rewrite a vague ending (“We should talk sometime”) as a clear professional next step.","minWords":20},{"prompt":"Draft stage: Write a 50–70 word closing to a conversation after a workshop.","minWords":50},{"prompt":"Final rewrite and transfer: write a complete professional ending that includes time signal, warm close, next action, deadline and final sentence.","minWords":75}]},"review":{"keywords":"time signal · warm close · next action · deadline","mission":"Open, maintain and close a complete four-minute conversation."}},{"id":"w3l7","number":7,"week":3,"title":"Describe your work clearly","outcome":"Explain your role, team and responsibilities to someone outside your field.","expressions":[{"text":"My main responsibility is…","job":"name your most important duty","cloze":"My main ___ is…","answer":"responsibility","choices":["responsibility","response","responsible"]},{"text":"I work closely with…","job":"describe collaboration","cloze":"I work ___ with…","answer":"closely","choices":["closely","close","closed"]},{"text":"A typical task involves…","job":"explain a regular activity","cloze":"A typical task ___…","answer":"involves","choices":["involves","involve","involving"]},{"text":"The purpose of my role is to…","job":"explain why your job exists","cloze":"The ___ of my role is to…","answer":"purpose","choices":["purpose","result","position"]},{"text":"In simple terms…","job":"make technical information accessible","cloze":"In ___ terms…","answer":"simple","choices":["simple","simply","small"]}],"grammar":{"focus":"Present simple for regular duties; gerunds after “involves”; clear noun phrases for roles and departments.","items":[{"q":"Choose the correct duty sentence.","options":["My main responsibility is checking quality.","My main responsibility are checking quality.","My main responsible is check quality."],"answer":"My main responsibility is checking quality.","tag":"grammar:be"},{"q":"Choose the correct collaboration sentence.","options":["I work closely with the finance team.","I works closely with finance team.","I close work with the finance team."],"answer":"I work closely with the finance team.","tag":"grammar:present-simple"},{"q":"Choose the correct “involves” pattern.","options":["A typical task involves preparing reports.","A typical task involves prepare reports.","A typical task involve preparing reports."],"answer":"A typical task involves preparing reports.","tag":"grammar:gerund"},{"q":"Complete: The purpose of my role is ___ support customers.","options":["to","for","at"],"answer":"to","tag":"grammar:infinitive"},{"q":"Choose the clearest noun phrase.","options":["the customer support team","support customer the team","the team customer supporting"],"answer":"the customer support team","tag":"grammar:noun-phrase"},{"q":"Choose the correct third-person form.","options":["She manages client requests.","She manage client requests.","She managing client requests."],"answer":"She manages client requests.","tag":"grammar:third-person"},{"q":"Choose the simple explanation.","options":["In simple terms, I help projects stay on schedule.","In terms simple I project schedule.","Simply terms I helping schedule."],"answer":"In simple terms, I help projects stay on schedule.","tag":"grammar:clarity"},{"q":"Complete: I usually ___ progress data every Friday.","options":["collect","collects","collecting"],"answer":"collect","tag":"grammar:present-simple"},{"q":"Choose the correct question about work.","options":["Who do you work closely with?","Who you work closely with?","Who does you work close with?"],"answer":"Who do you work closely with?","tag":"grammar:question-form"},{"q":"Choose the best result sentence.","options":["The result of my work is a clear weekly update.","The result my work are clear update.","My work result clear weekly."],"answer":"The result of my work is a clear weekly update.","tag":"grammar:noun-phrase"}]},"listening":{"title":"My work in simple terms","questions":[{"q":"What does the speaker avoid at the beginning?","options":["Technical language","Simple explanations","Examples"],"answer":"Technical language","tag":"listening:strategy"},{"q":"In simple terms, what does the speaker do?","options":["Helps projects stay organised and on schedule","Repairs computers","Teaches children"],"answer":"Helps projects stay organised and on schedule","tag":"listening:main-idea"},{"q":"What is the main responsibility?","options":["Collect progress information and make clear updates","Design buildings","Hire all staff"],"answer":"Collect progress information and make clear updates","tag":"listening:detail"},{"q":"What does a typical task include first?","options":["Checking what has been completed","Buying equipment","Calling customers"],"answer":"Checking what has been completed","tag":"listening:sequence"},{"q":"What problem does the speaker identify?","options":["Anything that is late","Only spelling mistakes","Personal disagreements"],"answer":"Anything that is late","tag":"listening:detail"},{"q":"Who does the speaker work with?","options":["Field staff, supervisors and finance","Only the manager","Only outside customers"],"answer":"Field staff, supervisors and finance","tag":"listening:detail"},{"q":"Why are several teams involved?","options":["Each group has part of the needed information","The speaker wants more meetings","No one has any information"],"answer":"Each group has part of the needed information","tag":"listening:reason"},{"q":"What is the purpose of the role?","options":["Help managers understand progress and decide next steps","Make reports longer","Avoid project decisions"],"answer":"Help managers understand progress and decide next steps","tag":"listening:purpose"},{"q":"What is the useful result of an update?","options":["Notice problems early and keep work moving","Create more technical vocabulary","Delay decisions"],"answer":"Notice problems early and keep work moving","tag":"listening:inference"},{"q":"What communication principle is demonstrated?","options":["Explain work so an outsider can understand it","Use as much jargon as possible","List job titles without explaining them"],"answer":"Explain work so an outsider can understand it","tag":"listening:main-idea"}]},"writing":{"tasks":[{"prompt":"Write your job or study role in simple terms.","minWords":5},{"prompt":"Write one sentence beginning “My main responsibility is…”","minWords":5},{"prompt":"Write one sentence beginning “I work closely with…”","minWords":5},{"prompt":"Write one sentence beginning “A typical task involves…”","minWords":5},{"prompt":"Write the purpose of your role using “The purpose of my role is to…”","minWords":5},{"prompt":"Explain one technical word from your field in simple English.","minWords":10},{"prompt":"Write 3 sentences about role, task and collaborators.","minWords":20},{"prompt":"Write 40–60 words explaining your work to a 12-year-old.","minWords":40},{"prompt":"Draft stage: Add the result or value of your work to create a 60–80 word explanation.","minWords":60},{"prompt":"Final rewrite and transfer: write an 80–100 word “My work in simple terms” explanation with no unexplained technical words.","minWords":80}]},"review":{"keywords":"role · main task · collaborators · purpose · result","mission":"Give a two-minute “My work in simple terms” explanation."}},{"id":"w3l8","number":8,"week":3,"title":"Routines and current priorities","outcome":"Compare regular responsibilities with what you are working on now.","expressions":[{"text":"I usually spend my mornings…","job":"describe a normal routine","cloze":"I ___ spend my mornings…","answer":"usually","choices":["usually","current","today"]},{"text":"At the moment, I’m working on…","job":"name a current assignment","cloze":"At the ___, I’m working on…","answer":"moment","choices":["moment","minute","time"]},{"text":"Most weeks, I…","job":"describe a frequent pattern","cloze":"___ weeks, I…","answer":"Most","choices":["Most","Much","Many"]},{"text":"This week is different because…","job":"contrast routine and present","cloze":"This ___ is different because…","answer":"week","choices":["week","weeks","weekly"]},{"text":"My top priority today is…","job":"identify the most urgent task","cloze":"My top ___ today is…","answer":"priority","choices":["priority","prior","important"]}],"grammar":{"focus":"Present simple versus present continuous; adverbs of frequency.","items":[{"q":"Choose the routine sentence.","options":["I usually review plans in the morning.","I am usually reviewing plans every morning now.","I usually reviewing plans."],"answer":"I usually review plans in the morning.","tag":"grammar:present-simple"},{"q":"Choose the current-action sentence.","options":["At the moment, I’m preparing a report.","At the moment, I prepare a report every day.","At the moment, I preparing report."],"answer":"At the moment, I’m preparing a report.","tag":"grammar:present-continuous"},{"q":"Complete: Most weeks, I ___ with colleagues.","options":["coordinate","am coordinating","coordinates"],"answer":"coordinate","tag":"grammar:present-simple"},{"q":"Complete: This week, I ___ on a special project.","options":["am working","work every","works"],"answer":"am working","tag":"grammar:present-continuous"},{"q":"Choose the correct adverb position.","options":["I usually check email at 8 a.m.","I check usually email at 8 a.m.","Usually I am check email."],"answer":"I usually check email at 8 a.m.","tag":"grammar:adverb-frequency"},{"q":"Choose the correct negative current action.","options":["I’m not working on that task today.","I don’t working on that task today.","I not am work on that task."],"answer":"I’m not working on that task today.","tag":"grammar:present-continuous"},{"q":"Choose the correct routine question.","options":["What do you usually do in the morning?","What are you usually do morning?","What you usually doing every morning?"],"answer":"What do you usually do in the morning?","tag":"grammar:question-form"},{"q":"Choose the current question.","options":["What are you working on at the moment?","What do you working at moment?","What are you work on?"],"answer":"What are you working on at the moment?","tag":"grammar:question-form"},{"q":"Complete: My top priority today ___ finishing the client update.","options":["is","are","be"],"answer":"is","tag":"grammar:be"},{"q":"Choose the best contrast.","options":["I usually work on reports, but this week I’m preparing a presentation.","I am usually report but week prepare presentation.","Usually I working reports because presentation."],"answer":"I usually work on reports, but this week I’m preparing a presentation.","tag":"grammar:contrast"}]},"listening":{"title":"My normal week and today’s priority","questions":[{"q":"How does the speaker describe most weeks?","options":["Predictable","Completely different every day","Very quiet"],"answer":"Predictable","tag":"listening:main-idea"},{"q":"What does the speaker usually do first?","options":["Check messages and review the day’s plan","Prepare a presentation","Call customers immediately"],"answer":"Check messages and review the day’s plan","tag":"listening:sequence"},{"q":"What happens after that?","options":["Coordinate with colleagues and update the task list","Go home","Start a new job"],"answer":"Coordinate with colleagues and update the task list","tag":"listening:sequence"},{"q":"What is a normal afternoon activity?","options":["Preparing notes or reports","Attending school","Cooking"],"answer":"Preparing notes or reports","tag":"listening:detail"},{"q":"Why is this week different?","options":["There is an important Thursday deadline","The office is closed","The speaker is on holiday"],"answer":"There is an important Thursday deadline","tag":"listening:reason"},{"q":"What is the speaker working on now?","options":["Final details for a client update","A new building","A job interview"],"answer":"Final details for a client update","tag":"listening:detail"},{"q":"What is the speaker waiting for?","options":["Two pieces of information","A new computer","A salary payment"],"answer":"Two pieces of information","tag":"listening:detail"},{"q":"What is today’s top priority?","options":["Finish the update before 4 p.m.","Read every email again","Change the task list"],"answer":"Finish the update before 4 p.m.","tag":"listening:priority"},{"q":"What happens to normal duties?","options":["They receive less time until the deadline is complete","They disappear permanently","They become more important than the deadline"],"answer":"They receive less time until the deadline is complete","tag":"listening:inference"},{"q":"Which grammar contrast is central to the message?","options":["Routine present simple vs current present continuous","Past perfect vs future perfect","Passive voice only"],"answer":"Routine present simple vs current present continuous","tag":"listening:language"}]},"writing":{"tasks":[{"prompt":"Write one normal weekly duty using present simple.","minWords":5},{"prompt":"Write another routine sentence with “usually”.","minWords":5},{"prompt":"Write one current task using present continuous.","minWords":5},{"prompt":"Write one sentence beginning “At the moment…”","minWords":5},{"prompt":"Write today’s top priority.","minWords":5},{"prompt":"Write one contrast sentence beginning “This week is different because…”","minWords":10},{"prompt":"Write 3 sentences: routine, current task and priority.","minWords":20},{"prompt":"Write a short work log with five routine statements and three current-action statements.","minWords":40},{"prompt":"Draft stage: Write 60–80 words comparing a normal week with this week.","minWords":60},{"prompt":"Final rewrite and transfer: write an 80–100 word update titled “My normal work and my current priority.”","minWords":80}]},"review":{"keywords":"routine 1 · routine 2 · current task · priority","mission":"Speak for two minutes about “My normal work and my current priority.”"}},{"id":"w3l9","number":9,"week":3,"title":"Give a useful work update","outcome":"Report progress, completed actions, current work and next steps.","expressions":[{"text":"So far, I’ve completed…","job":"report completed progress","cloze":"So ___, I’ve completed…","answer":"far","choices":["far","long","now"]},{"text":"I’m currently checking…","job":"describe work in progress","cloze":"I’m ___ checking…","answer":"currently","choices":["currently","current","nowly"]},{"text":"The main issue is…","job":"identify a blocker","cloze":"The main ___ is…","answer":"issue","choices":["issue","problematic","thingy"]},{"text":"I expect to finish by…","job":"give a realistic deadline","cloze":"I ___ to finish by…","answer":"expect","choices":["expect","expects","waiting"]},{"text":"My next step is to…","job":"state the immediate action","cloze":"My ___ step is to…","answer":"next","choices":["next","new","later"]}],"grammar":{"focus":"Present perfect for progress; present continuous for current work; future language for next action and deadline.","items":[{"q":"Choose the correct progress sentence.","options":["So far, I’ve completed the first review.","So far, I completed the first review every day.","So far, I am complete first review."],"answer":"So far, I’ve completed the first review.","tag":"grammar:present-perfect"},{"q":"Choose the current-work sentence.","options":["I’m currently checking the final details.","I currently checked final details now.","I’m currently check final details."],"answer":"I’m currently checking the final details.","tag":"grammar:present-continuous"},{"q":"Choose the blocker sentence.","options":["The main issue is one missing document.","The main issue are missing document one.","Main issue one document missing is."],"answer":"The main issue is one missing document.","tag":"grammar:be"},{"q":"Complete: I expect to finish ___ 3 p.m.","options":["by","at until","on"],"answer":"by","tag":"grammar:deadline"},{"q":"Choose the next-step sentence.","options":["My next step is to update the plan.","My next step is updating to the plan.","My next step update plan is."],"answer":"My next step is to update the plan.","tag":"grammar:infinitive"},{"q":"Choose the correct progress question.","options":["What have you completed so far?","What did you completed so far?","What have you complete so far?"],"answer":"What have you completed so far?","tag":"grammar:present-perfect-question"},{"q":"Choose the correct current question.","options":["What are you working on now?","What do you working on now?","What are you work now?"],"answer":"What are you working on now?","tag":"grammar:present-continuous-question"},{"q":"Choose the realistic future sentence.","options":["I expect to receive it today.","I expecting receive it yesterday tomorrow.","I expect receiving it today to."],"answer":"I expect to receive it today.","tag":"grammar:infinitive"},{"q":"Choose the best contrast.","options":["I’ve completed the review, and I’m now checking the final details.","I completed now and checking yesterday.","I’ve complete review but currently checked."],"answer":"I’ve completed the review, and I’m now checking the final details.","tag":"grammar:tense-contrast"},{"q":"Choose the clearest update order.","options":["completed progress → current work → issue → deadline → next step","issue → unrelated story → greeting → hobby","next year → past childhood → current task"],"answer":"completed progress → current work → issue → deadline → next step","tag":"grammar:organisation"}]},"listening":{"title":"A clear work update","questions":[{"q":"What is the purpose of the message?","options":["Give a quick work update","Introduce a new employee","End a workshop conversation"],"answer":"Give a quick work update","tag":"listening:main-idea"},{"q":"What has already been completed?","options":["The first review","The final presentation","The supplier contract"],"answer":"The first review","tag":"listening:progress"},{"q":"How many sections were corrected?","options":["Two","Five","One"],"answer":"Two","tag":"listening:detail"},{"q":"What is happening now?","options":["Checking final details and confirming numbers","Writing a job application","Starting the first review"],"answer":"Checking final details and confirming numbers","tag":"listening:current-work"},{"q":"Who is helping confirm the numbers?","options":["The finance team","A school teacher","The customer’s family"],"answer":"The finance team","tag":"listening:detail"},{"q":"What is the main issue?","options":["One missing supplier document","A broken computer","A missing employee"],"answer":"One missing supplier document","tag":"listening:blocker"},{"q":"What has the speaker done about the issue?","options":["Requested the document","Cancelled the project","Ignored it"],"answer":"Requested the document","tag":"listening:action"},{"q":"When is the full update expected to finish?","options":["By 3 p.m.","Next week","At midnight yesterday"],"answer":"By 3 p.m.","tag":"listening:deadline"},{"q":"What is the next step after receiving the document?","options":["Add it, check the final version, and send the plan","Begin the first review again","Change the client"],"answer":"Add it, check the final version, and send the plan","tag":"listening:sequence"},{"q":"Does the speaker expect the deadline to change?","options":["No","Yes, definitely","The speaker gives no opinion"],"answer":"No","tag":"listening:inference"}]},"writing":{"tasks":[{"prompt":"Write one sentence about something you have completed so far.","minWords":5},{"prompt":"Write one sentence about what you are currently working on.","minWords":5},{"prompt":"Write one sentence identifying a main issue.","minWords":5},{"prompt":"Write one realistic deadline using “I expect to finish by…”","minWords":5},{"prompt":"Write one next step using “My next step is to…”","minWords":5},{"prompt":"Write a two-sentence update: completed progress + current work.","minWords":15},{"prompt":"Add one blocker and what you are doing about it.","minWords":20},{"prompt":"Write a 50–70 word update using all five target expressions.","minWords":50},{"prompt":"Draft stage: Rewrite a vague update (“Things are going okay”) as a specific useful update.","minWords":50},{"prompt":"Final rewrite and transfer: write an 80–110 word professional work update in this order: progress, current work, issue, deadline, next step.","minWords":80}]},"review":{"keywords":"progress · current work · issue · deadline · next step","mission":"Give a 60–90 second work update with completed progress, current work, blocker, deadline and next step."}}],"levelNote":"Adult/professional communicative pathway: supported A2+ practice moving toward functional B1 independence."};
