function bookMeta(id){return getDB().books?.find(b=>b.id===id)||null}
function studentClass(sid){const u=getDB().users.find(x=>x.id===sid);return getDB().classes.find(c=>u?.classIds?.includes(c.id))||null}
function bookIdForStudent(sid){const c=studentClass(sid);return c?.bookId||c?.course_id||'career-fluency'}
function courseForStudent(sid){return BOOK_PACKS[bookIdForStudent(sid)]||CAREER_FLUENCY_BOOK}
function readyLessons(course=COURSE){return course.lessons.filter(l=>l.ready!==false)}
function setActiveBook(id){if(!BOOK_PACKS[id])return false;activeBookId=id;COURSE=BOOK_PACKS[id];if(!COURSE.lessons.some(l=>l.id===activeLessonId&&l.ready!==false))activeLessonId=readyLessons(COURSE)[0]?.id||COURSE.lessons[0]?.id;return true}
function syncActiveBook(){if(!session||session.role!=='student')return;setActiveBook(bookIdForStudent(session.id))}
function lessonById(id){for(const c of Object.values(BOOK_PACKS)){const hit=c.lessons.find(l=>l.id===id);if(hit)return hit}return null}
function skillLabel(k){return k==='listening'?'Listening & Reading':cap(k)}


const NAV={student:[['home','⌂','Home'],['progress','◔','Progress']],teacher:[['teacher-home','⌂','Overview'],['students','◎','Students'],['classes','▤','Classes'],['weaknesses','△','Needs review'],['reports','▦','Reports']],admin:[['admin-home','⌂','Overview'],['admin-books','▣','Books'],['admin-classes','▤','Classes'],['admin-teachers','◎','Teachers'],['admin-students','○','Students']]};
let session=null,currentPage='home',activeLessonId='w1l1',currentStep='vocabulary',apiDB=null;
function getDB(){return apiDB||{version:6,books:[],users:[],classes:[],profiles:{},attempts:[],completion:{},writing:{},listeningLocks:{}}}
function saveDB(db){apiDB=db}
function $(id){return document.getElementById(id)} function lesson(id=activeLessonId){return lessonById(id)||COURSE.lessons[0]} function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}
async function api(path,options={}){const opts={credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options};const res=await fetch(path,opts);let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||'Request failed');return data}
async function refreshState(){apiDB=await api('/api/state');syncActiveBook();return apiDB}
function init(){$('loginForm').addEventListener('submit',e=>{e.preventDefault();login($('username').value.trim(),$('password').value)});$('logoutBtn').addEventListener('click',logout);$('menuBtn').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'))} document.addEventListener('DOMContentLoaded',init);
async function login(username,password){$('loginError').textContent='';try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username,password})});session=r.user;await refreshState();$('loginScreen').classList.add('hidden');$('app').classList.remove('hidden');$('app').classList.remove('student-mode','teacher-mode','admin-mode');$('app').classList.add(session.role+'-mode');$('sidebarName').textContent=session.name;$('sidebarRole').textContent=session.role==='admin'?'System Admin':session.role==='teacher'?'Teacher':'Student';$('sidebarAvatar').textContent=session.name[0];currentPage=session.role==='admin'?'admin-home':session.role==='teacher'?'teacher-home':'home';renderNav();renderPage()}catch(e){$('loginError').textContent=e.message||'Username or password is incorrect.'}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}session=null;apiDB=null;$('app').classList.add('hidden');$('loginScreen').classList.remove('hidden');$('password').value=''}
function renderNav(){const items=NAV[session.role],html=items.map(([id,icon,label])=>`<button class="nav-btn ${currentPage===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('');if(session.role==='student'){$('sideNav').innerHTML='';$('studentTopNav').innerHTML=html;$('bottomNav').innerHTML=html+`<button class="nav-btn ${currentPage==='profile'?'active':''}" data-page="profile"><span class="nav-icon">○</span>Profile</button>`;$('studentProfileBtn').classList.remove('hidden');$('studentProfileBtn').textContent=session.name[0]}else{$('sideNav').innerHTML=html;$('studentTopNav').innerHTML='';$('bottomNav').innerHTML=html;$('studentProfileBtn').classList.add('hidden')}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.page;document.querySelector('.sidebar').classList.remove('open');renderNav();renderPage()});$('studentProfileBtn').onclick=()=>{currentPage='profile';renderNav();renderPage()}}
function title(e,h){$('pageEyebrow').textContent=e;$('pageTitle').textContent=h} function progress(v){return `<div class="progress"><span style="width:${Math.max(0,Math.min(100,v))}%"></span></div>`} function renderPage(){session.role==='student'?renderStudent():session.role==='teacher'?renderTeacher():renderAdmin()} function renderStudent(){({home:studentHome,workbook,course:studentCourse,progress:studentProgress,leaderboard:()=>leaderboard(false),profile}[currentPage]||studentHome)()} function renderTeacher(){({'teacher-home':teacherHome,students,classes,weaknesses,reports}[currentPage]||teacherHome)()} function renderAdmin(){({'admin-home':adminHome,'admin-books':adminBooks,'admin-book-browse':adminBookBrowse,'admin-workbook':adminBooks,'admin-workbook-view':adminWorkbookView,'admin-classes':adminClasses,'admin-teachers':adminTeachers,'admin-students':adminStudents}[currentPage]||adminHome)()}
function attempts(sid,skill=null,lid=null){return getDB().attempts.filter(a=>a.studentId===sid&&(!skill||a.skill===skill)&&(!lid||a.lessonId===lid))} function mastery(sid,skill){const db=getDB(),base=db.profiles?.[sid]?.base?.[skill]??60,a=attempts(sid,skill);if(!a.length)return base;const best={};a.forEach(x=>best[x.lessonId]=Math.max(best[x.lessonId]||0,x.score));const vals=Object.values(best),avg=Math.round(vals.reduce((p,c)=>p+c,0)/vals.length);return Math.round(base*.35+avg*.65)} function overall(sid){return Math.round(['vocabulary','grammar','listening','writing'].reduce((a,k)=>a+mastery(sid,k),0)/4)} function points(sid){return getDB().profiles?.[sid]?.points||0}
function completionFor(sid,lid){return getDB().completion?.[sid]?.[lid]||[]} function skillCompletionFor(sid,lid){return completionFor(sid,lid).filter(x=>WORKBOOK_STEPS.includes(x))} function lessonProgress(sid,lid){return Math.round(skillCompletionFor(sid,lid).length/WORKBOOK_STEPS.length*100)} function completionPct(sid){const c=courseForStudent(sid),total=c.totalLessons||c.lessons.length||1,done=c.lessons.reduce((n,l)=>n+skillCompletionFor(sid,l.id).length,0);return Math.round(done/(total*WORKBOOK_STEPS.length)*100)} function writingFor(sid,lid){return getDB().writing?.[sid]?.[lid]||''}
function weakest(sid){const r=['vocabulary','listening','grammar','writing'].map(k=>[k,mastery(sid,k)]).sort((a,b)=>a[1]-b[1]),k=r[0][0],tips={vocabulary:'Review the words and expressions that are not yet automatic.',listening:'Practise finding the main idea and key details in short texts and audio.',grammar:'Review the grammar pattern needed for this lesson topic.',writing:'Build clearer sentences, then organise them into a complete written response.'};return{key:k,label:skillLabel(k),score:r[0][1],tip:tips[k]}}
function skillCard(n,v,d){return `<div class="card metric-card"><div class="metric-top"><span class="pill">${d}</span><strong>${v}%</strong></div><h4 style="margin:0">${n}</h4>${progress(v)}</div>`} function metric(l,v,s){return `<div class="card metric-card"><span class="pill">${s}</span><strong>${v}</strong><h4 style="margin:0">${l}</h4></div>`}
function studentHome(){const sid=session.id;setActiveBook(bookIdForStudent(sid));const b=bookMeta(activeBookId)||{title:COURSE.title||COURSE.moduleTitle,level:COURSE.level,totalLessons:COURSE.totalLessons||COURSE.lessons.length},ready=readyLessons(COURSE),next=ready.find(l=>skillCompletionFor(sid,l.id).length<WORKBOOK_STEPS.length),pct=completionPct(sid);title('EnglishGate Workbook','Home');if(!next){$('content').innerHTML=`<div class="student-home"><section class="next-action-card module-complete-card"><div class="next-action-copy"><span class="pill teal">Available workbook complete</span><p class="student-kicker">${escapeHtml(b.title)}</p><h1>You finished the available practice.</h1><p>Your completed vocabulary, listening & reading, grammar and writing evidence is saved. More book lessons can be added without changing your class.</p><div class="student-cta-row"><button class="primary-btn student-primary-cta" id="viewCourseBtn">View my book →</button><button class="ghost-btn" id="openProgressBtn">Progress</button></div></div><div class="next-action-number"><span>${pct}%</span><small>BOOK</small></div></section></div>`;$('viewCourseBtn').onclick=()=>{currentPage='course';renderNav();studentCourse()};$('openProgressBtn').onclick=()=>{currentPage='progress';renderNav();studentProgress()};return}const step=firstOpenStep(sid,next.id),done=skillCompletionFor(sid,next.id).length,total=b.totalLessons||COURSE.totalLessons||COURSE.lessons.length;$('content').innerHTML=`<div class="student-home"><section class="next-action-card book-home-card"><div class="next-action-copy"><span class="pill teal">${escapeHtml(b.level||COURSE.level||'')}</span><p class="student-kicker">${escapeHtml(b.title)}</p><h1>${WORKBOOK_LABELS[step]}</h1><h2>Lesson ${next.number} · ${escapeHtml(next.title)}</h2><p>${escapeHtml(next.outcome||'')}</p><div class="next-progress"><div><span>${done}/4 skill pages complete</span><strong>${lessonProgress(sid,next.id)}%</strong></div>${progress(lessonProgress(sid,next.id))}</div><div class="student-cta-row"><button class="primary-btn student-primary-cta" id="continueBtn">Open ${WORKBOOK_LABELS[step]} →</button><button class="ghost-btn" id="viewCourseBtn">My book</button></div></div><div class="next-action-number"><span>${next.number}</span><small>OF ${total}</small></div></section><section class="student-glance"><div class="glance-card"><span class="glance-icon">▣</span><div><small>Book progress</small><strong>${pct}%</strong><p>${points(sid)} points earned</p></div><button class="text-link" id="openProgressBtn">See progress →</button></div><div class="glance-card quiet"><span class="glance-icon">4</span><div><small>Workbook focus</small><strong>Four skills</strong><p>Vocabulary · Listening & Reading · Grammar · Writing</p></div></div></section></div>`;const open=()=>{activeLessonId=next.id;currentStep=step;currentPage='workbook';renderNav();workbook()};$('continueBtn').onclick=open;$('viewCourseBtn').onclick=()=>{currentPage='course';renderNav();studentCourse()};$('openProgressBtn').onclick=()=>{currentPage='progress';renderNav();studentProgress()}}
function studentCourse(){const sid=session.id;setActiveBook(bookIdForStudent(sid));const b=bookMeta(activeBookId)||{title:COURSE.title||COURSE.moduleTitle,level:COURSE.level,totalLessons:COURSE.totalLessons||COURSE.lessons.length};title('EnglishGate Workbook','My Book');$('content').innerHTML=`<section class="course-shell"><button class="back-link" id="courseHome">← Home</button><div class="course-intro"><div><span class="pill teal">${escapeHtml(b.level||'')}</span><h1>${escapeHtml(b.title)}</h1><p>The live class handles speaking and fluency. This workbook builds vocabulary, listening & reading, grammar and writing around the same course topics.</p></div><div class="course-overall"><strong>${completionPct(sid)}%</strong><span>Book progress</span>${progress(completionPct(sid))}</div></div><div class="course-path">${COURSE.lessons.map(l=>{const pct=lessonProgress(sid,l.id),ready=l.ready!==false,complete=pct===100;return `<button class="course-topic ${complete?'complete':''} ${ready?'current':'pending'}" data-topic="${ready?l.id:''}" ${ready?'':'disabled'}><span class="topic-state">${complete?'✓':ready?'→':'○'}</span><span class="topic-copy"><small>Lesson ${l.number}</small><strong>${escapeHtml(l.title)}</strong><span>${complete?'Completed':ready?`${WORKBOOK_LABELS[firstOpenStep(sid,l.id)]} next`:'Workbook activity coming next'}</span></span><span class="topic-progress">${ready?pct+'%':'—'}</span></button>`}).join('')}</div></section>`;$('courseHome').onclick=()=>{currentPage='home';renderNav();studentHome()};document.querySelectorAll('[data-topic]').forEach(btn=>{if(!btn.dataset.topic)return;btn.onclick=()=>{activeLessonId=btn.dataset.topic;currentStep=firstOpenStep(sid,activeLessonId);currentPage='workbook';renderNav();workbook()}})}
function listeningLocked(lid){return Boolean(getDB().listeningLocks?.[session.id]?.includes(lid))||completionFor(session.id,lid).includes('listening')}
async function loadListeningPrep(l){const box=$('listeningTranscript');if(!box)return;try{const r=await api(`/api/listening/${l.id}/prep`);if(r.locked){await refreshState();renderActivity();return}box.innerHTML=`<p>${escapeHtml(r.script)}</p>`}catch(e){box.innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}
async function lockListeningScript(l){const btn=$('readyForQuestions'),msg=$('listeningGateMessage');if(!btn)return;btn.disabled=true;btn.textContent='Locking script…';try{await api(`/api/listening/${l.id}/lock`,{method:'POST'});await refreshState();renderActivity()}catch(e){btn.disabled=false;btn.textContent='Done reading & listening — start questions';if(msg)msg.innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}
function isAdminWorkbookPreview(){return session?.role==='admin'&&currentPage==='admin-workbook-view'}
function firstOpenStep(sid,lid){return WORKBOOK_STEPS.find(step=>!skillCompletionFor(sid,lid).includes(step))||WORKBOOK_STEPS[WORKBOOK_STEPS.length-1]}
function workbook(){const sid=session.id,l=lesson(),steps=WORKBOOK_STEPS,idx=steps.indexOf(currentStep),preview=isAdminWorkbookPreview(),completed=preview?steps:skillCompletionFor(sid,l.id),firstOpen=preview?steps.length-1:steps.indexOf(firstOpenStep(sid,l.id));title(`Lesson ${l.number}`,WORKBOOK_LABELS[currentStep]);$('content').innerHTML=`<section class="learning-shell jtbd-shell ${preview?'admin-preview-workbook':''}"><div class="jtbd-workbook-head"><button class="back-link" id="exitWorkbook">← ${preview?'Books':'My book'}</button><div class="jtbd-current-job"><small>${escapeHtml(COURSE.title||COURSE.moduleTitle||'Workbook')} · Lesson ${l.number}${preview?' · Preview':''}</small><strong>${escapeHtml(l.title)}</strong></div><span class="jtbd-step-count">${idx+1}/4</span></div><div class="skill-tabs">${steps.map((step,i)=>{const allowed=preview||completed.includes(step)||i<=firstOpen;return `<button class="skill-tab ${step===currentStep?'active':''} ${completed.includes(step)?'complete':''}" data-skill-tab="${allowed?step:''}" ${allowed?'':'disabled'}><span>${completed.includes(step)?'✓':i+1}</span>${WORKBOOK_LABELS[step]}</button>`}).join('')}</div><div id="activityPanel" class="activity-card focused-activity jtbd-activity-panel"></div></section>`;$('exitWorkbook').onclick=()=>{if(preview){currentPage='admin-book-browse';renderNav();adminBookBrowse()}else{currentPage='course';renderNav();studentCourse()}};document.querySelectorAll('[data-skill-tab]').forEach(btn=>{if(!btn.dataset.skillTab)return;btn.onclick=()=>{currentStep=btn.dataset.skillTab;workbook()}});renderActivity()}
function renderActivity(){const p=$('activityPanel'),l=lesson();if(currentStep==='vocabulary')p.innerHTML=vocabActivity(l);if(currentStep==='listening')p.innerHTML=listeningActivity(l);if(currentStep==='grammar')p.innerHTML=grammarActivity(l);if(currentStep==='writing')p.innerHTML=writingActivity(l);wireActivity(l)}
function buildVocabQuestions(l){const e=l.expressions,all=e.map(x=>x.text);return [
{type:'choice',stage:'Recognise',q:`Which expression would you use to ${e[0].job}?`,options:all,answer:e[0].text,tag:'vocabulary:meaning'},
{type:'choice',stage:'Recognise',q:`Which expression would you use to ${e[1].job}?`,options:all,answer:e[1].text,tag:'vocabulary:meaning'},
{type:'choice',stage:'Retrieve',q:`Complete from memory: ${e[2].cloze}`,options:e[2].choices,answer:e[2].answer,tag:'vocabulary:retrieval'},
{type:'choice',stage:'Retrieve',q:`Complete from memory: ${e[3].cloze}`,options:e[3].choices,answer:e[3].answer,tag:'vocabulary:retrieval'},
{type:'choice',stage:'Retrieve',q:`Complete from memory: ${e[4].cloze}`,options:e[4].choices,answer:e[4].answer,tag:'vocabulary:retrieval'},
{type:'choice',stage:'Apply',q:`In the ${l.title.toLowerCase()} mission, you need to ${e[2].job}. Which expression fits best?`,options:all,answer:e[2].text,tag:'vocabulary:context'},
{type:'choice',stage:'Apply',q:`A partner needs language to ${e[3].job}. What should they say?`,options:all,answer:e[3].text,tag:'vocabulary:context'},
{type:'exact',stage:'Repair',q:`Repair the phrase by typing the missing word: ${e[0].cloze}`,answer:e[0].answer,min:1,tag:'vocabulary:repair'},
{type:'open',stage:'Personalise',q:`Write one true sentence about your own life or work using “${e[1].text}”`,min:6,tag:'vocabulary:personalisation'},
{type:'open',stage:'Produce',q:`Without looking back, write three useful expressions from this topic that you could use in this live mission: ${l.review.mission}`,min:10,tag:'vocabulary:independent-retrieval'}]}
function stageBadge(label){return `<span class="stage-badge">${label}</span>`}
function openEvidence(name,q,min,tag,exact=''){return `<div class="open-evidence"><textarea name="${name}" data-open="1" data-min="${min}" data-tag="${escapeAttr(tag||'')}" ${exact?`data-exact="${escapeAttr(exact)}"`:''} placeholder="Type your answer…"></textarea><small class="muted">${exact?'Type the missing/corrected language.':`Write at least ${min} words.`}</small></div>`}
function spiralReview(l){const idx=COURSE.lessons.findIndex(x=>x.id===l.id);if(idx===0)return `<div class="spiral-card"><strong>First-topic retrieval</strong><p>Close the language bank. Recall three expressions from today, then say one true sentence with each.</p></div>`;const prev=COURSE.lessons[idx-1],older=COURSE.lessons[Math.max(0,idx-3)];const pExp=prev.expressions[0],oExp=older.expressions[1];return `<div class="spiral-grid"><div class="spiral-card"><span class="stage-badge">20% · Previous topic</span><strong>${prev.title}</strong><p>Recall the expression used to ${pExp.job}. Then use it in one new sentence.</p><details><summary>Check expression</summary><p>${pExp.text}</p></details></div><div class="spiral-card"><span class="stage-badge">10% · Older topic</span><strong>${older.title}</strong><p>Recall one expression for this communication job: ${oExp.job}.</p><details><summary>Check expression</summary><p>${oExp.text}</p></details></div><div class="spiral-card"><span class="stage-badge">Transfer</span><strong>Combine old + new</strong><p>Use one expression from an earlier topic and one from today in a two-sentence response.</p></div></div>`}
function moduleChallengeHtml(){return `<div class="class-prep-challenge"><strong>Final module prep</strong><label><input type="checkbox" data-challenge> Choose 5 keywords for your talk.</label><label><input type="checkbox" data-challenge> Recall 6 useful expressions without looking.</label><label><input type="checkbox" data-challenge> Practise your 3-minute talk once.</label></div>`}

function guidedChunks(chunks){const items=chunks.flatMap(c=>c.items.map(item=>({stage:c.label,item}))),total=items.length;return `<div class="activity-runner" data-activity-runner><div class="runner-meta"><span data-runner-stage>${escapeHtml(items[0]?.stage||'Practice')}</span><span><b data-runner-current>1</b> / ${total}</span></div><div class="runner-progress"><span data-runner-progress style="width:${total?100/total:100}%"></span></div><div class="runner-question-stack" data-runner-stack>${items.map((x,i)=>`<div class="runner-question" data-runner-question data-stage="${escapeAttr(x.stage)}" ${i?'hidden':''}>${x.item}</div>`).join('')}</div><div class="runner-actions"><button class="runner-back" type="button" data-runner-prev hidden>Back</button><button class="primary-btn runner-next" type="button" data-runner-next disabled>${total===1?'Finish':'Next'}</button></div></div>`}
function wireMcqCards(root=document){root.querySelectorAll('.mcq-picker').forEach(picker=>{if(picker.dataset.wired==='1')return;picker.dataset.wired='1';const slot=picker.querySelector('[data-mcq-slot]'),slotText=picker.querySelector('[data-mcq-slot-text]'),cards=[...picker.querySelectorAll('[data-mcq-option]')],inputs=[...picker.querySelectorAll('[data-mcq-input]')];if(!slot||!slotText||!cards.length)return;const animateToSlot=card=>{const from=card.getBoundingClientRect(),to=slot.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='mcq-fly-card';ghost.textContent=card.dataset.value||card.textContent.trim();ghost.style.left=from.left+'px';ghost.style.top=from.top+'px';ghost.style.width=from.width+'px';ghost.style.height=from.height+'px';document.body.appendChild(ghost);requestAnimationFrame(()=>{ghost.style.transform=`translate(${to.left+to.width/2-(from.left+from.width/2)}px,${to.top+to.height/2-(from.top+from.height/2)}px) scale(.78)`;ghost.style.opacity='.15'});setTimeout(()=>ghost.remove(),280)};const choose=(card,animate=true)=>{const i=Number(card.dataset.mcqOption),input=inputs.find(x=>Number(x.dataset.mcqInput)===i);if(!input)return;inputs.forEach(x=>x.checked=false);cards.forEach(x=>x.classList.remove('selected'));input.checked=true;input.dispatchEvent(new Event('change',{bubbles:true}));card.classList.add('selected');slot.classList.add('filled');slotText.textContent=card.dataset.value||card.textContent.trim();if(animate)animateToSlot(card);if(slot.animate)slot.animate([{transform:'scale(.985)'},{transform:'scale(1.02)'},{transform:'scale(1)'}],{duration:240,easing:'ease-out'})};cards.forEach(card=>{card.onclick=()=>choose(card,true);card.ondragstart=e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',card.dataset.mcqOption);card.classList.add('dragging')};card.ondragend=()=>card.classList.remove('dragging')});slot.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';slot.classList.add('drag-over')};slot.ondragleave=()=>slot.classList.remove('drag-over');slot.ondrop=e=>{e.preventDefault();slot.classList.remove('drag-over');const i=Number(e.dataTransfer.getData('text/plain')),card=cards.find(x=>Number(x.dataset.mcqOption)===i);if(card)choose(card,false)};slot.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&cards.length){e.preventDefault();const selected=cards.findIndex(x=>x.classList.contains('selected')),next=cards[(selected+1)%cards.length];choose(next,true)}}})}

function wireGuidedActivity(){const runner=document.querySelector('[data-activity-runner]');if(!runner)return;const cards=[...runner.querySelectorAll('[data-runner-question]')],prev=runner.querySelector('[data-runner-prev]'),next=runner.querySelector('[data-runner-next]'),current=runner.querySelector('[data-runner-current]'),stage=runner.querySelector('[data-runner-stage]'),bar=runner.querySelector('[data-runner-progress]');if(!cards.length||!next)return;let index=0;const answered=card=>Boolean(card.querySelector('input[type="radio"]:checked')||[...card.querySelectorAll('textarea,input[type="text"]')].some(el=>el.value.trim().length>0));const sync=()=>{cards.forEach((card,i)=>card.hidden=i!==index);if(current)current.textContent=String(index+1);if(stage)stage.textContent=cards[index].dataset.stage||'Practice';if(bar)bar.style.width=`${((index+1)/cards.length)*100}%`;if(prev){prev.hidden=index===0;prev.disabled=index===0}next.textContent=index===cards.length-1?'Finish':'Next';next.disabled=!answered(cards[index]);setTimeout(()=>wireMcqCards(cards[index]),0)};const move=i=>{index=Math.max(0,Math.min(cards.length-1,i));sync();runner.scrollIntoView({behavior:'smooth',block:'start'})};runner.addEventListener('change',()=>sync());runner.addEventListener('input',()=>sync());if(prev)prev.onclick=()=>move(index-1);next.onclick=()=>{if(!answered(cards[index]))return;if(index<cards.length-1){move(index+1);return}const submit=$('checkActivity')||$('saveWriting');if(submit)submit.click()};sync()}
function vocabActivity(l){const qs=(l.vocabulary?.items||buildVocabQuestions(l)).slice(0,10);return `<div class="activity-one-page"><div class="skill-page-head"><div><span class="pill teal">Vocabulary</span><h2>${escapeHtml(l.title)}</h2></div><strong>10 questions · one page</strong></div><div class="activity-question-list">${qs.map((q,i)=>`<article class="guided-question"><div class="question-stage"><span>Question ${i+1}</span><b>${i+1}/10</b></div><p>${escapeHtml(q.q)}</p>${q.type&&q.type!=='choice'?openEvidence('v'+i,q.q,q.min||1,q.tag,q.type==='exact'?q.answer:''):radio('v'+i,q.options,q.answer,q.tag)}</article>`).join('')}</div><div id="activityFeedback"></div><button class="primary-btn guided-submit skill-submit" id="checkActivity">Check Vocabulary</button></div>`}
function listeningActivity(l){const qs=(l.listening?.questions||[]).slice(0,10),hasText=Boolean(l.listening?.text);return `<div class="activity-one-page"><div class="skill-page-head"><div><span class="pill teal">Listening & Reading</span><h2>${escapeHtml(l.listening?.title||l.title)}</h2></div><strong>10 questions · one page</strong></div>${hasText?`<section class="source-panel"><div class="source-panel-head"><div><small>Read + listen</small><strong>${escapeHtml(l.listening.title)}</strong></div><button id="playAudio" class="play-btn" title="Play audio">▶</button></div><p>${escapeHtml(l.listening.text)}</p><span id="audioStatus" class="muted">Read once, then listen and check what you understood.</span></section>`:`<section class="source-panel compact-source"><div class="source-panel-head"><div><small>Listen</small><strong>${escapeHtml(l.listening?.title||l.title)}</strong></div><button id="playAudio" class="play-btn">▶</button></div><span id="audioStatus" class="muted">Listen for the main idea, then replay for details.</span></section>`}<div class="activity-question-list">${qs.map((q,i)=>`<article class="guided-question"><div class="question-stage"><span>Question ${i+1}</span><b>${i+1}/10</b></div><p>${escapeHtml(q.q)}</p>${radio('l'+i,q.options,q.answer,q.tag)}</article>`).join('')}</div><div id="activityFeedback"></div><button class="primary-btn guided-submit skill-submit" id="checkActivity">Check Listening & Reading</button></div>`}
function grammarActivity(l){const qs=(l.grammar?.items||[]).slice(0,10);return `<div class="activity-one-page"><div class="skill-page-head"><div><span class="pill teal">Grammar</span><h2>${escapeHtml(l.grammar?.focus||l.title)}</h2></div><strong>10 questions · one page</strong></div><div class="activity-question-list">${qs.map((q,i)=>`<article class="guided-question"><div class="question-stage"><span>Question ${i+1}</span><b>${i+1}/10</b></div><p>${escapeHtml(q.q)}</p>${radio('g'+i,q.options,q.answer,q.tag)}</article>`).join('')}</div><div id="activityFeedback"></div><button class="primary-btn guided-submit skill-submit" id="checkActivity">Check Grammar</button></div>`}
function boostHint(q){const tag=String(q.tag||'');const rules=[
['question','Look at the word order. English questions often need a helping verb before the subject.'],
['infinitive','After language about a goal or something you want to do, look for “to + base verb”.'],
['present-simple','Check the subject first, then choose the present-simple form that agrees with it.'],
['negative','A present-simple negative normally uses do/does + not + the base verb.'],
['connector-because','Use “because” when the second idea gives a reason.'],
['connector-but','Use “but” when the second idea contrasts with the first.'],
['connector-so','Use “so” when the second idea is a result.'],
['connector','Decide whether the ideas show addition, contrast, reason or result.'],
['gerund','After “responsible for”, the next verb normally uses the -ing form.'],
['be','Check whether the subject needs am, is or are.'],
['collocation','Use the fixed phrase from the lesson rather than translating word by word.'],
['time-phrase','Check which preposition naturally introduces the time expression.'],
['complete-sentence','Look for a complete subject + verb + idea.'],
['do','Check the subject before choosing do or does.']
];const hit=rules.find(([key])=>tag.includes(key));return hit?hit[1]:'Compare the choices with the model language from this topic. Read the whole sentence, not just one word.'}
function boostRecovery(l){const core=[...attempts(session.id,'grammar',l.id)].reverse().find(a=>!(a.tags||[]).some(t=>String(t).startsWith('boost:')));if(!core)return{ready:false,reason:'Try and check the grammar activity first.',missed:[]};const tags=core.tags||[],missed=[...new Set(tags.filter(t=>/^missq:[0-9]$/.test(String(t))).map(t=>Number(String(t).split(':')[1])))].sort((a,b)=>a-b),diagnosed=tags.includes('diagnostic:no-misses')||missed.length>0;if(!diagnosed)return{ready:false,reason:'Check the grammar activity once more so EnglishGate can identify the exact questions you miss.',missed:[]};if(!missed.length)return{ready:false,reason:'No Boost is needed. You did not miss any automatically checked grammar questions in your latest attempt.',missed:[]};return{ready:true,reason:'',missed,core}}
function boostFreshQuestion(q){const tag=String(q.tag||'');if(tag.includes('question'))return{q:'Choose the correctly formed question.',options:['Where do they use English?','Where they use English?','Where does they use English?'],answer:'Where do they use English?'};if(tag.includes('third-person'))return{q:'Complete: Amina ___ with international clients every week.',options:['works','work','working'],answer:'works'};if(tag.includes('negative'))return{q:'Choose the correct negative sentence.',options:['He does not need more time.','He not needs more time.','He does not needs more time.'],answer:'He does not need more time.'};if(tag.includes('present-simple'))return{q:'Choose the accurate routine sentence.',options:['I usually practise English after work.','I usually practises English after work.','I am usually practise English after work.'],answer:'I usually practise English after work.'};if(tag.includes('infinitive'))return{q:'Complete: My next goal is ___ lead a larger project.',options:['to','for','at'],answer:'to'};if(tag.includes('gerund'))return{q:'Complete: She is responsible for ___ the weekly schedule.',options:['checking','check','to check'],answer:'checking'};if(tag.includes('because'))return{q:'Choose the best connector: I practise every day ___ I want to speak more confidently.',options:['because','but','so'],answer:'because'};if(tag.includes('but')||tag.includes('contrast'))return{q:'Choose the best connector: I understand the topic, ___ I need more time to answer.',options:['but','because','so'],answer:'but'};if(tag.includes('connector-so'))return{q:'Choose the best connector: I have a presentation tomorrow, ___ I am practising tonight.',options:['so','but','because'],answer:'so'};if(tag.includes('modal'))return{q:'Complete: You ___ ask the speaker to repeat the question.',options:['can','are','have'],answer:'can'};if(tag.includes('present-perfect'))return{q:'Complete: I ___ worked with this team for two years.',options:['have','has','am'],answer:'have'};if(tag.includes('present-continuous'))return{q:'Complete: We ___ preparing the final report now.',options:['are','do','have'],answer:'are'};if(tag.includes('will')||tag.includes('deadline'))return{q:'Complete: I ___ send the final version tomorrow morning.',options:['will','am','have'],answer:'will'};if(tag.includes('be'))return{q:'Complete: My main challenge ___ speaking without long pauses.',options:['is','are','be'],answer:'is'};if(tag.includes('have'))return{q:'Complete: I ___ two main responsibilities in my current role.',options:['have','has','having'],answer:'have'};if(tag.includes('complete-sentence'))return{q:'Choose the complete sentence.',options:['We use English at work.','We English at work.','Use English work.'],answer:'We use English at work.'};return{q:'Fresh practice for the same grammar rule: '+q.q,options:q.options,answer:q.answer}}
function startBoost(l){if(!l.grammar?.items?.length)return;const recovery=boostRecovery(l);if(!recovery.ready){showModal('<div class="boost-modal boost-result"><span class="boost-kicker">EnglishGate Boost</span><h3>Boost is not ready yet</h3><p>'+escapeHtml(recovery.reason)+'</p><button class="primary-btn" id="boostBack">Back to grammar</button></div>');$('boostBack').onclick=closeModal;return}const qs=recovery.missed.map(i=>({index:i,original:l.grammar.items[i],retest:boostFreshQuestion(l.grammar.items[i])})).filter(x=>x.original);renderBoost(l,{questions:qs,index:0,wrong:0,hints:0,totalAttempts:0,mastered:0,unresolved:0,saving:false,feedback:''})}
function renderBoost(l,state){const item=state.questions[state.index],q=item.retest,original=item.original,lesson=boostHint(original);showModal('<div class="boost-modal"><div class="boost-modal-head"><div><span class="boost-kicker">EnglishGate Boost · Targeted recovery</span><h3>Fix what you missed</h3><p>Question '+(state.index+1)+' of '+state.questions.length+' missed grammar skill'+(state.questions.length===1?'':'s')+'.</p></div><button class="icon-btn" data-close>×</button></div><div class="boost-flow"><span class="active">1 · Review</span><span class="active">2 · Retest</span><span>3 · Mastery</span></div><div class="boost-question-card"><div class="boost-original"><small>Workbook question you missed</small><strong>'+escapeHtml(original.q)+'</strong></div><div class="boost-mini"><strong>Mini lesson</strong><span>'+escapeHtml(lesson)+'</span><small>Model answer from the original item: '+escapeHtml(original.answer)+'</small></div><div class="question-stage">'+stageBadge('Fresh retest')+'<span>'+(state.index+1)+'/'+state.questions.length+'</span></div><p class="boost-question">'+escapeHtml(q.q)+'</p>'+radio('boostChoice',q.options,q.answer,original.tag)+(state.wrong?'<div class="boost-hint"><strong>Try once more</strong><span>'+escapeHtml(lesson)+'</span></div>':'')+'<div id="boostFeedback">'+(state.feedback?'<div class="feedback bad">'+escapeHtml(state.feedback)+'</div>':'')+'</div><button class="primary-btn boost-submit" id="boostSubmit">Check retest answer</button></div><p class="boost-note">The retest changes the context so you apply the rule instead of memorising the old answer.</p></div>');document.querySelector('[data-close]').onclick=closeModal;wireMcqCards(document.getElementById('modalRoot')||document);$('boostSubmit').onclick=()=>submitBoost(l,state)}
async function submitBoost(l,state){const selected=document.querySelector('input[name="boostChoice"]:checked');if(!selected){$('boostFeedback').innerHTML='<div class="feedback bad">Choose an answer first.</div>';return}const item=state.questions[state.index];state.totalAttempts++;if(selected.value===item.retest.answer){state.mastered++;state.feedback='';state.wrong=0;state.index++;if(state.index>=state.questions.length){await finishBoost(l,state);return}renderBoost(l,state);return}state.wrong++;state.hints++;if(state.wrong<2){state.feedback='Not yet. Read the mini lesson and try this fresh question once more.';renderBoost(l,state);return}state.unresolved++;state.feedback='';state.wrong=0;state.index++;if(state.index>=state.questions.length){await finishBoost(l,state);return}renderBoost(l,state)}
async function finishBoost(l,state){if(state.saving)return;state.saving=true;const total=state.questions.length,score=Math.round(state.mastered/Math.max(1,total)*100),mastered=state.unresolved===0&&state.mastered===total,tags=['boost:retest','boost:grammar',mastered?'boost:mastered':'boost:needs-practice',...state.questions.slice(0,7).map(x=>'boostq:'+x.index)].slice(0,10);try{await recordAttempt(session.id,l.id,'grammar',score,tags);await refreshState();showModal('<div class="boost-modal boost-result"><div class="boost-result-icon">'+(mastered?'✓':'↻')+'</div><span class="boost-kicker">EnglishGate Boost</span><h3>'+(mastered?'Missed grammar repaired':'Some grammar still needs practice')+'</h3><p>'+(mastered?'You reviewed the rules and answered fresh retest questions successfully. Your original workbook score remains saved separately.':'Your recovery result has been saved. Run Boost again after your next grammar attempt if these skills are still missed.')+'</p><div class="boost-result-grid"><div><small>Original misses</small><strong>'+total+'</strong></div><div><small>Recovered</small><strong>'+state.mastered+'</strong></div><div><small>Boost mastery</small><strong>'+score+'%</strong></div></div><button class="primary-btn" id="boostBack">Back to grammar</button></div>');$('boostBack').onclick=()=>{closeModal();renderActivity()}}catch(e){state.saving=false;state.feedback='Could not save Boost progress: '+e.message;renderBoost(l,state)}}
function writingResponses(sid,lid){const raw=writingFor(sid,lid);if(!raw)return [];try{const parsed=JSON.parse(raw);return Array.isArray(parsed)?parsed:[]}catch{return [raw]}}
function writingActivity(l){const saved=writingResponses(session.id,l.id),tasks=(l.writing?.tasks||[]).slice(0,10);return `<div class="activity-one-page"><div class="skill-page-head"><div><span class="pill teal">Writing</span><h2>${escapeHtml(l.title)}</h2></div><strong>10 tasks · one page</strong></div><div class="activity-question-list">${tasks.map((t,i)=>`<article class="guided-question writing-guided-question"><div class="writing-task-head"><div><span class="stage-badge">Task ${i+1}</span><strong>${escapeHtml(t.prompt)}</strong></div><span>${t.minWords}+ words</span></div><textarea class="writing-response" data-writing="${i}" data-min="${t.minWords}" placeholder="Write your answer here…">${escapeHtml(saved[i]||'')}</textarea><div class="word-count" data-count="${i}">0 words</div></article>`).join('')}</div><div id="activityFeedback"></div><button class="primary-btn guided-submit skill-submit" id="saveWriting">Save Writing</button></div>`}
function reviewActivity(l){const w=isAdminWorkbookPreview()?{label:'Student focus'}:weakest(session.id),firstTopic=l.number===1,retrieval=firstTopic?'Recall 3 useful expressions from this topic and say one sentence with each.':`Recall 1 useful expression from the previous topic and use it in one new sentence.`;return `<div class="class-prep"><div class="class-prep-focus"><span>Focus</span><strong>${escapeHtml(w.label)}</strong></div><section class="class-prep-mission"><span class="role-kicker">Live class mission</span><h2>${escapeHtml(l.review.mission)}</h2><div class="keyword-line"><small>Keywords</small><strong>${escapeHtml(l.review.keywords)}</strong></div></section><section class="class-prep-recall"><span class="role-kicker">Before class</span><p>${escapeHtml(retrieval)}</p></section>${l.number===9?moduleChallengeHtml():''}<div id="activityFeedback"></div><button class="primary-btn class-prep-ready" id="finishReview">${l.number===9?'Module prep complete':'I’m ready for class →'}</button></div>`}

function radio(name,options,answer,tag=''){return `<div class="mcq-picker" data-mcq="${escapeAttr(name)}"><div class="mcq-answer-slot" data-mcq-slot tabindex="0" aria-label="Selected answer"><span class="mcq-slot-label">Your answer</span><strong data-mcq-slot-text>Choose one option below</strong><small>Tap a card or drag it here</small></div><div class="mcq-option-cards">${options.map((o,i)=>`<button class="mcq-option-card" type="button" draggable="true" data-mcq-option="${i}" data-value="${escapeAttr(o)}"><span class="mcq-option-index">${String.fromCharCode(65+i)}</span><span class="mcq-option-text">${escapeHtml(o)}</span></button><input class="mcq-native-input" type="radio" name="${name}" value="${escapeAttr(o)}" data-answer="${escapeAttr(answer)}" data-tag="${escapeAttr(tag)}" data-mcq-input="${i}" tabindex="-1" aria-hidden="true">`).join('')}</div></div>`}
const audioCache={};
async function playListening(l){const btn=$('playAudio'),status=$('audioStatus');if(!btn)return;try{btn.disabled=true;btn.textContent='…';status.textContent='Loading natural voice…';let url=audioCache[l.id];if(!url){const res=await fetch(`/api/audio/${l.id}`,{credentials:'include'});if(!res.ok){let msg='Natural audio is unavailable.';try{const d=await res.json();msg=d.error||msg}catch{}throw new Error(msg)}const blob=await res.blob();url=URL.createObjectURL(blob);audioCache[l.id]=url}const audio=new Audio(url);status.textContent='Playing · listen without reading a transcript';btn.textContent='❚❚';audio.onended=()=>{btn.disabled=false;btn.textContent='▶';status.textContent='Finished. Replay for detail when you are ready.'};audio.onerror=()=>{btn.disabled=false;btn.textContent='▶';status.textContent='Audio playback failed.'};await audio.play()}catch(e){btn.disabled=false;btn.textContent='▶';status.textContent=e.message}}
function wireActivity(l){wireMcqCards();if($('playAudio'))$('playAudio').onclick=()=>playListening(l);document.querySelectorAll('.writing-response').forEach(t=>{const update=()=>{const n=t.value.trim()?t.value.trim().split(/\s+/).length:0,c=document.querySelector(`[data-count="${t.dataset.writing}"]`);if(c)c.textContent=`${n} words · minimum ${t.dataset.min}`};t.oninput=update;update()});if(isAdminWorkbookPreview()){const steps=WORKBOOK_STEPS,idx=steps.indexOf(currentStep),ready=readyLessons(COURSE),advance=()=>{if(idx<steps.length-1){currentStep=steps[idx+1];workbook();return}const li=ready.findIndex(x=>x.id===activeLessonId);if(li>=0&&li<ready.length-1){activeLessonId=ready[li+1].id;currentStep='vocabulary';workbook()}else{currentPage='admin-book-browse';renderNav();adminBookBrowse()}};if($('checkActivity')){$('checkActivity').textContent=idx===steps.length-1?'Finish preview':'Next skill →';$('checkActivity').onclick=advance}if($('saveWriting')){$('saveWriting').textContent='Finish preview';$('saveWriting').onclick=advance}return}if($('boostActivity'))$('boostActivity').onclick=()=>startBoost(l);if($('checkActivity'))$('checkActivity').onclick=checkCurrent;if($('saveWriting'))$('saveWriting').onclick=()=>saveWriting(l)}
async function saveWriting(l){const boxes=[...document.querySelectorAll('.writing-response')],responses=boxes.map(t=>t.value.trim()),f=$('activityFeedback');let met=0;boxes.forEach(t=>{const n=t.value.trim()?t.value.trim().split(/\s+/).length:0;if(n>=Number(t.dataset.min))met++});if(met<10){f.innerHTML=`<div class="feedback bad">Complete all 10 writing tasks to the minimum length. You have completed ${met}/10.</div>`;return}const score=100;try{await api(`/api/writing/${l.id}`,{method:'PUT',body:JSON.stringify({content:JSON.stringify(responses),score})});await refreshState();if(skillCompletionFor(session.id,l.id).length===WORKBOOK_STEPS.length){currentPage='home';renderNav();studentHome();return}currentStep=firstOpenStep(session.id,l.id);workbook()}catch(e){f.innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}
async function checkCurrent(){const total=10;let correct=0,tags=[],grammarMissed=[];document.querySelectorAll('[data-open="1"]').forEach(el=>{const value=el.value.trim(),exact=el.dataset.exact||'',min=Number(el.dataset.min||1);let ok=false;if(exact)ok=value.toLowerCase().replace(/[.?!]/g,'').trim()===exact.toLowerCase().replace(/[.?!]/g,'').trim();else ok=(value?value.split(/\s+/).length:0)>=min;if(ok)correct++;if(el.dataset.tag)tags.push(el.dataset.tag)});const groups=[...new Set([...document.querySelectorAll('input[type=radio]')].map(x=>x.name))];groups.forEach(g=>{const c=document.querySelector(`input[name="${g}"]:checked`),isGrammarAuto=currentStep==='grammar'&&/^g[0-9]$/.test(g);if(c&&c.value===c.dataset.answer)correct++;else if(isGrammarAuto)grammarMissed.push(Number(g.slice(1)));if(c&&c.dataset.tag)tags.push(c.dataset.tag)});if(currentStep==='grammar')tags=grammarMissed.length?grammarMissed.map(i=>`missq:${i}`):['diagnostic:no-misses'];const score=Math.round(correct/total*100),feedback=$('activityFeedback');if(feedback)feedback.innerHTML=`<div class="feedback ${score>=70?'good':'bad'}"><strong>${score}%</strong> · ${correct}/${total} correct.</div>`;try{await recordAttempt(session.id,activeLessonId,currentStep,score,tags);if(score>=70)await markDone(session.id,activeLessonId,currentStep);await refreshState();if(currentStep==='grammar'&&grammarMissed.length){if(feedback){feedback.innerHTML=`<div class="jtbd-result"><div><strong>${score}%</strong><span>${grammarMissed.length} grammar question${grammarMissed.length===1?'':'s'} to fix</span></div><button class="primary-btn" id="boostFromResult">Fix missed questions</button></div>`;const b=$('boostFromResult');if(b)b.onclick=()=>startBoost(lesson())}return}if(score>=70){currentStep=firstOpenStep(session.id,activeLessonId);setTimeout(workbook,450)}}catch(e){if(feedback)feedback.innerHTML=`<div class="feedback bad">Could not save progress: ${escapeHtml(e.message)}</div>`}}
async function recordAttempt(studentId,lessonId,skill,score,tags=[]){await api('/api/attempts',{method:'POST',body:JSON.stringify({lessonId,skill,score,tags:[...new Set(tags)]})})}
async function markDone(studentId,lid,step){await api('/api/completion',{method:'POST',body:JSON.stringify({lessonId:lid,step})})}
function studentProgress(){const sid=session.id,w=weakest(sid),ats=attempts(sid).slice(-5).reverse(),c=courseForStudent(sid),b=bookMeta(bookIdForStudent(sid))||{title:c.title||c.moduleTitle};title('EnglishGate Workbook','Progress');$('content').innerHTML=`<section class="progress-shell"><div class="progress-hero-card"><div><span class="pill teal">${escapeHtml(b.title)}</span><h1>${completionPct(sid)}% complete</h1><p>Workbook evidence covers only vocabulary, listening & reading, grammar and writing. Speaking and fluency stay in the live class.</p></div><button class="ghost-btn" id="progressCourseBtn">My book</button></div><div class="student-skill-grid">${['vocabulary','listening','grammar','writing'].map(k=>skillCard(skillLabel(k),mastery(sid,k),mastery(sid,k)>=75?'On track':'Keep practising')).join('')}</div><section class="section student-progress-grid"><div class="card"><span class="pill gold">Recommended workbook review</span><h3>${w.label} · ${w.score}%</h3><p>${w.tip}</p>${progress(w.score)}</div><div class="card"><span class="pill">Practice</span><h3>${points(sid)} points</h3><p>Points reward completed workbook practice and successful retries.</p></div></section><section class="section card"><div class="section-head"><div><h3>Recent practice</h3><p>Your latest five workbook attempts.</p></div></div>${ats.length?ats.map(a=>`<div class="attempt-row"><div><strong>${escapeHtml(lessonById(a.lessonId)?.title||'Lesson')} · ${skillLabel(a.skill)}</strong><span>${new Date(a.at).toLocaleDateString()}</span></div><strong>${a.score}%</strong></div>`).join(''):'<p class="muted">Complete an activity to start your evidence history.</p>'}</section></section>`;$('progressCourseBtn').onclick=()=>{currentPage='course';renderNav();studentCourse()}}
function profile(){const u=getDB().users.find(x=>x.id===session.id)||session,c=studentClass(session.id),b=bookMeta(bookIdForStudent(session.id)),teacher=getDB().users.find(x=>x.id===c?.teacher_id);title('EnglishGate Workbook','Profile');$('content').innerHTML=`<section class="profile-shell"><div class="card profile-card"><div class="profile-avatar-large">${escapeHtml(u.name[0])}</div><h2>${escapeHtml(u.name)}</h2><p class="muted">${escapeHtml(b?.title||'Workbook')}</p><div class="profile-row"><span>Class</span><strong>${escapeHtml(c?.name||'—')}</strong></div><div class="profile-row"><span>Teacher</span><strong>${escapeHtml(teacher?.name||'—')}</strong></div><div class="profile-row"><span>Username</span><strong>${escapeHtml(u.username)}</strong></div><button class="ghost-btn" id="resetHelp">Password help</button><button class="ghost-btn danger-action" id="studentLogout">Sign out</button></div></section>`;$('resetHelp').onclick=()=>alert('Ask your teacher to reset your password.');$('studentLogout').onclick=logout}
function teacherClassIds(){return getDB().classes.map(c=>c.id)} function classStudents(){const ids=teacherClassIds();return getDB().users.filter(u=>u.role==='student'&&u.classIds?.some(id=>ids.includes(id)))}
function teacherHome(){const sts=classStudents(),active=sts.filter(s=>attempts(s.id).length>0).length,avgComp=sts.length?Math.round(sts.reduce((a,s)=>a+completionPct(s.id),0)/sts.length):0,priority=sts.filter(s=>weakest(s.id).score<65),cw=aggregateWeaknesses()[0];title('Teacher','Overview');$('content').innerHTML=`<section class="role-hero"><div><span class="role-kicker">Your classes</span><h1>What needs your attention?</h1><p>Manage students and use workbook evidence to decide what to revise next.</p></div><button class="primary-btn" id="quickAddStudent">+ Add student</button></section><section class="admin-metrics">${metric('Students',sts.length,'Your roster')}${metric('Active',active,'Has practice')}${metric('Completion',avgComp+'%','Average')}${metric('Need support',priority.length,'Below 65%')}</section><section class="section grid grid-2"><div class="card action-card"><span class="role-kicker">Next teaching move</span><h3>${cw?.label||'Collect practice evidence'}</h3><p>${cw?`${cw.count} student${cw.count===1?'':'s'} currently show this as their weakest skill.`:'Students need to complete workbook practice before a class pattern appears.'}</p><button class="secondary-btn" id="openWeak">Open needs review</button></div><div class="card"><div class="section-head"><div><h3>Recent students</h3><p>Open a learner to review progress.</p></div><button class="text-link" id="openStudents">View all</button></div>${sts.slice(0,5).map(s=>`<button class="compact-person-row" data-review-student="${s.id}"><span class="avatar">${escapeHtml(s.name[0])}</span><span><strong>${escapeHtml(s.name)}</strong><small>${completionPct(s.id)}% complete · ${weakest(s.id).label}</small></span><b>→</b></button>`).join('')||'<p class="muted">No students yet.</p>'}</div></section>`; $('quickAddStudent').onclick=openAddStudent;$('openWeak').onclick=()=>{currentPage='weaknesses';renderNav();weaknesses()};$('openStudents').onclick=()=>{currentPage='students';renderNav();students()};document.querySelectorAll('[data-review-student]').forEach(b=>b.onclick=()=>openStudentDetail(b.dataset.reviewStudent))}
function students(){const sts=classStudents();title('Teacher','Students');$('content').innerHTML=`<div class="role-page-head"><div><span class="role-kicker">Roster</span><h1>Your students</h1><p>Students in classes assigned to you.</p></div><button class="primary-btn" id="addStudent">+ Add student</button></div><div class="card table-wrap clean-table"><table class="data-table"><thead><tr><th>Student</th><th>Class</th><th>Progress</th><th>Focus</th><th></th></tr></thead><tbody>${sts.map(s=>studentRow(s)).join('')}</tbody></table></div>`;$('addStudent').onclick=openAddStudent;document.querySelectorAll('[data-review-student]').forEach(b=>b.onclick=()=>openStudentDetail(b.dataset.reviewStudent))}
function studentRow(s){const w=weakest(s.id),className=getDB().classes.find(c=>s.classIds?.includes(c.id))?.name||'—';return `<tr><td><div class="student-cell"><div class="avatar">${escapeHtml(s.name[0])}</div><div><strong>${escapeHtml(s.name)}</strong><div class="muted">@${escapeHtml(s.username)}</div></div></div></td><td>${escapeHtml(className)}</td><td>${completionPct(s.id)}%</td><td>${w.label}</td><td><button class="ghost-btn" data-review-student="${s.id}">Review</button></td></tr>`}
function openAddStudent(){const cls=getDB().classes;if(!cls.length){showModal(`<div class="section-head"><div><span class="role-kicker">Students</span><h3>No class assigned</h3><p class="muted">A System Admin must assign at least one class before you can create students.</p></div><button class="icon-btn" data-close>×</button></div>`);document.querySelector('[data-close]').onclick=closeModal;return}showModal(`<div class="section-head"><div><span class="role-kicker">New student</span><h3>Create student access</h3></div><button class="icon-btn" data-close>×</button></div><form id="studentForm" class="form-grid"><label>Student name<input id="newName" required></label><label>Username<input id="newUsername" required placeholder="e.g. ahmed.ali"></label><label>Class<select id="newClass">${cls.map(c=>`<option value="${c.id}">${escapeHtml(c.name)} · ${escapeHtml(bookMeta(c.bookId||c.course_id)?.title||c.level)}</option>`).join('')}</select></label><button class="primary-btn" type="submit">Create student</button></form><div id="createResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('studentForm').onsubmit=async e=>{e.preventDefault();const name=$('newName').value.trim(),username=$('newUsername').value.trim().toLowerCase(),classId=$('newClass').value;try{const r=await api('/api/teacher/students',{method:'POST',body:JSON.stringify({name,username,classId})});await refreshState();$('createResult').innerHTML=`<div class="credential-card"><span>Student created</span><strong>@${escapeHtml(r.username)}</strong><code>${escapeHtml(r.temporaryPassword)}</code><small>Copy this temporary password now. It will not be shown again.</small></div>`}catch(err){$('createResult').innerHTML=`<div class="feedback bad">${escapeHtml(err.message)}</div>`}}}
function openStudentDetail(id){const db=getDB(),st=db.users.find(u=>u.id===id),w=weakest(id),ats=attempts(id).slice(-10).reverse(),c=studentClass(id),b=bookMeta(bookIdForStudent(id));showModal(`<div class="section-head"><div><p class="eyebrow">${escapeHtml(b?.title||'Workbook')}</p><h3>${escapeHtml(st.name)}</h3><p class="muted">${escapeHtml(c?.name||'')}</p></div><button class="icon-btn" data-close>×</button></div><div class="grid grid-4 compact-grid">${['vocabulary','listening','grammar','writing'].map(k=>skillCard(skillLabel(k),mastery(id,k),'Mastery')).join('')}</div><div class="weakness section"><strong>Workbook priority: ${w.label} · ${w.score}%</strong><span>${w.tip}</span></div><div class="section-head section"><div><h3>Recent attempts</h3><p>Evidence from workbook practice.</p></div><button class="ghost-btn" id="resetPass">Reset password</button></div>${ats.length?ats.map(a=>`<div class="attempt-row"><div><strong>Lesson ${lessonById(a.lessonId)?.number||'—'} · ${skillLabel(a.skill)} ${(a.tags||[]).some(t=>String(t).startsWith('boost:'))?'<span class="pill teal">Boost</span>':''}</strong><span>${new Date(a.at).toLocaleString()}</span></div><strong>${a.score}%</strong></div>`).join(''):'<p class="muted">No activity attempts yet.</p>'}<div id="resetResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('resetPass').onclick=async()=>{try{const r=await api(`/api/teacher/students/${id}/reset-password`,{method:'POST'});$('resetResult').innerHTML=`<div class="feedback good">Temporary password: <code>${escapeHtml(r.temporaryPassword)}</code></div>`}catch(e){$('resetResult').innerHTML=`<div class="feedback bad">${escapeHtml(e.message)}</div>`}}}
function classes(){const cls=getDB().classes;title('Teacher','Classes');$('content').innerHTML=`<div class="role-page-head"><div><span class="role-kicker">Assigned to you</span><h1>Your classes</h1><p>Each class is connected to one book. The live class handles speaking and fluency; EnglishGate tracks the four workbook skills.</p></div></div><div class="class-card-grid">${cls.map(c=>{const sts=classStudents().filter(st=>st.classIds?.includes(c.id)),avg=sts.length?Math.round(sts.reduce((a,st)=>a+completionPct(st.id),0)/sts.length):0,b=bookMeta(c.bookId||c.course_id);return `<article class="management-card"><div class="management-card-head"><span class="pill teal">${escapeHtml(c.level)}</span><span>${sts.length} students</span></div><h3>${escapeHtml(c.name)}</h3><p class="book-line">Book: <strong>${escapeHtml(b?.title||c.course_id)}</strong></p><p>${avg}% average workbook completion</p>${progress(avg)}</article>`}).join('')||'<div class="empty-state"><h3>No classes yet</h3><p>Your System Admin must create a class and assign it to you.</p></div>'}</div>`}
function aggregateWeaknesses(){const map={};classStudents().forEach(s=>{const w=weakest(s.id);map[w.key]=map[w.key]||{key:w.key,label:w.label,count:0,total:0};map[w.key].count++;map[w.key].total+=w.score});return Object.values(map).map(x=>({...x,avg:Math.round(x.total/x.count)})).sort((a,b)=>b.count-a.count||a.avg-b.avg)}
function weaknesses(){const areas=aggregateWeaknesses();title('Teacher intelligence','Weakness map');$('content').innerHTML=`<div class="grid grid-2"><div class="card"><h3>Class-wide weaknesses</h3><p class="muted">Prioritised by how many students have each skill as their lowest area.</p>${areas.map(a=>`<div class="question"><div style="display:flex;justify-content:space-between"><strong>${a.label}</strong><span class="pill ${a.avg<65?'gold':'teal'}">${a.count} student${a.count!==1?'s':''}</span></div><div style="margin-top:10px">${progress(a.avg)}</div><small class="muted">Average mastery ${a.avg}%</small></div>`).join('')}</div><div><div class="recommendation"><p class="eyebrow">Best use of live time</p><h3>${areas[0]?.label||'Collect more evidence'}</h3><p>${areas[0]?`Start with a 10-minute revision targeting ${areas[0].label.toLowerCase()}. Then return immediately to the live speaking mission.`:'Have students complete workbook activities first.'}</p></div><div class="card section"><h3>Student-level priorities</h3>${classStudents().map(s=>`<p><strong>${s.name}:</strong> ${weakest(s.id).label} ${weakest(s.id).score}%</p>`).join('')}</div></div></div>`}
function reports(){const sts=classStudents(),ats=getDB().attempts,avgComp=sts.length?Math.round(sts.reduce((a,st)=>a+completionPct(st.id),0)/sts.length):0,avgMastery=sts.length?Math.round(sts.reduce((a,st)=>a+overall(st.id),0)/sts.length):0;title('Workbook evidence','Reports');$('content').innerHTML=`<div class="grid grid-3">${metric('Workbook completion',avgComp+'%','Across assigned books')}${metric('Average mastery',avgMastery+'%','4 tracked skills')}${metric('Attempts saved',ats.length,'Practice evidence')}</div><section class="section card"><div class="section-head"><div><h3>Evidence by student</h3><p>Workbook completion and mastery only. Speaking and fluency are observed in the live class.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Book</th><th>Completion</th><th>Overall</th><th>Attempts</th><th>Primary focus</th></tr></thead><tbody>${sts.map(st=>`<tr><td>${escapeHtml(st.name)}</td><td>${escapeHtml(bookMeta(bookIdForStudent(st.id))?.title||'—')}</td><td>${completionPct(st.id)}%</td><td>${overall(st.id)}%</td><td>${attempts(st.id).length}</td><td>${weakest(st.id).label}</td></tr>`).join('')}</tbody></table></div></section>`}
function leaderboard(teacher){title('Motivation','Class leaderboard');const data=classStudents().map(s=>({...s,points:points(s.id),completion:completionPct(s.id)})).sort((a,b)=>b.points-a.points);$('content').innerHTML=`<div class="card"><div class="section-head"><div><h3>Fluency Foundations · Module 1</h3><p>Points reward completion, attempts and successful practice — not English level alone.</p></div><span class="pill gold">Weekly</span></div>${data.map((s,i)=>`<div class="leader-row ${s.id===session.id&&!teacher?'me':''}"><div class="rank">${i+1}</div><div class="student-cell"><div class="avatar">${s.name[0]}</div><div><strong>${s.name}${s.id===session.id&&!teacher?' · You':''}</strong><div class="muted">${s.completion}% workbook complete</div></div></div><strong>${s.points} pts</strong></div>`).join('')}</div>`}
function adminBooks(){
  const books=getDB().books||[];
  title('System Admin','Books');
  $('content').innerHTML=`<section class="book-library">
    <div class="role-page-head"><div><span class="role-kicker">Curriculum browser</span><h1>Books</h1><p>System Admin can browse every digitized workbook without joining a class.</p></div></div>
    <div class="book-card-grid">
      ${books.map(b=>{
        const pack=BOOK_PACKS[b.id],readyCount=pack?readyLessons(pack).length:0,canUse=['ready','pilot'].includes(b.status)&&Boolean(pack);
        return `<article class="book-card">
          <div class="book-card-top"><span class="pill teal">${escapeHtml(b.level)}</span><span class="book-status ${b.status}">${b.status==='pilot'?'Pilot':b.status==='ready'?'Ready':'Queued'}</span></div>
          <div class="book-cover-mini"><span>EnglishGate</span><strong>${escapeHtml(b.title)}</strong><small>${b.totalLessons} lessons</small></div>
          <p>${escapeHtml(b.audience||'')}</p>
          <div class="book-card-meta"><span>${readyCount}/${b.totalLessons} digital lessons ready</span><span>Vocabulary · Listening & Reading · Grammar · Writing</span></div>
          <div class="book-card-actions">
            ${pack?`<button class="primary-btn" data-browse-book="${b.id}">Browse workbook</button>`:`<button class="ghost-btn" disabled>Not digitized yet</button>`}
            ${canUse?`<button class="ghost-btn" data-class-book="${b.id}">Create class</button>`:''}
          </div>
        </article>`;
      }).join('')}
    </div>
  </section>`;
  document.querySelectorAll('[data-browse-book]').forEach(btn=>btn.onclick=()=>{
    setActiveBook(btn.dataset.browseBook);
    currentPage='admin-book-browse';
    renderNav();
    adminBookBrowse();
  });
  document.querySelectorAll('[data-class-book]').forEach(btn=>btn.onclick=()=>openAdminClass(btn.dataset.classBook));
}
function adminBookBrowse(){const meta=bookMeta(activeBookId)||{title:COURSE.title||COURSE.moduleTitle,level:COURSE.level,totalLessons:COURSE.totalLessons||COURSE.lessons.length},lessons=COURSE.lessons||[];title('System Admin','Workbook');$('content').innerHTML=`<section class="admin-book-browser"><button class="back-link" id="adminBackBooks">← Books</button><div class="role-page-head"><div><span class="pill teal">${escapeHtml(meta.level||'')}</span><h1>${escapeHtml(meta.title||COURSE.title||COURSE.moduleTitle)}</h1><p>Read-only admin browsing. Open any digitized lesson and jump directly between all four skill pages.</p></div></div><div class="admin-browser-list">${lessons.map(l=>`<button class="admin-browser-lesson ${l.ready===false?'is-pending':''}" data-admin-browse-lesson="${l.ready===false?'':l.id}" ${l.ready===false?'disabled':''}><span class="admin-browser-num">${l.number}</span><span><strong>${escapeHtml(l.title)}</strong><small>${l.ready===false?'Workbook activities not built yet':escapeHtml(l.outcome||'All 4 skill pages available')}</small></span><b>${l.ready===false?'Not built':'Open →'}</b></button>`).join('')}</div></section>`;$('adminBackBooks').onclick=()=>{currentPage='admin-books';renderNav();adminBooks()};document.querySelectorAll('[data-admin-browse-lesson]').forEach(btn=>{if(!btn.dataset.adminBrowseLesson)return;btn.onclick=()=>{activeLessonId=btn.dataset.adminBrowseLesson;currentStep='vocabulary';currentPage='admin-workbook-view';renderNav();adminWorkbookView()}})}
function adminWorkbookView(){workbook()}

function adminUsers(role){return getDB().users.filter(u=>u.role===role)}
function adminHome(){const teachers=adminUsers('teacher'),students=adminUsers('student'),cls=getDB().classes,books=getDB().books||[],liveBooks=books.filter(b=>['ready','pilot'].includes(b.status)).length;title('System Admin','Overview');$('content').innerHTML=`<section class="role-hero admin-hero"><div><span class="role-kicker">EnglishGate setup</span><h1>Books power the classes.</h1><p>Choose the curriculum first. Every student then receives workbook activities from the book assigned to their class.</p></div><button class="primary-btn" id="adminOpenBooks">Open books</button></section><section class="admin-metrics">${metric('Books',books.length,liveBooks+' usable now')}${metric('Classes',cls.length,'Book-based cohorts')}${metric('Teachers',teachers.length,'Accounts')}${metric('Students',students.length,'Accounts')}</section><section class="section setup-flow"><div class="setup-step"><b>1</b><div><strong>Books</strong><span>Choose the curriculum.</span></div><button id="goBooks" class="text-link">Open</button></div><div class="setup-step"><b>2</b><div><strong>Classes</strong><span>Connect a book and teacher.</span></div><button id="goClasses" class="text-link">Open</button></div><div class="setup-step"><b>3</b><div><strong>Teachers & students</strong><span>Manage access and rosters.</span></div><button id="goTeachers" class="text-link">Open</button></div></section>`;const go=(page)=>{currentPage=page;renderNav();renderPage()};$('adminOpenBooks').onclick=()=>go('admin-books');$('goBooks').onclick=()=>go('admin-books');$('goClasses').onclick=()=>go('admin-classes');$('goTeachers').onclick=()=>go('admin-teachers')}
function adminClasses(){const cls=getDB().classes,teachers=adminUsers('teacher');title('System Admin','Classes');$('content').innerHTML=`<div class="role-page-head"><div><span class="role-kicker">Book-based cohorts</span><h1>Classes</h1><p>Each class has one book and one assigned teacher.</p></div><button class="primary-btn" id="newAdminClass">+ Create class</button></div><div class="class-card-grid">${cls.map(c=>{const t=teachers.find(x=>x.id===c.teacher_id),count=adminUsers('student').filter(st=>st.classIds?.includes(c.id)).length,b=bookMeta(c.bookId||c.course_id);return `<article class="management-card"><div class="management-card-head"><span class="pill teal">${escapeHtml(c.level)}</span><span>${count} students</span></div><h3>${escapeHtml(c.name)}</h3><p class="book-line">Book: <strong>${escapeHtml(b?.title||c.course_id)}</strong></p><p>Teacher: <strong>${escapeHtml(t?.name||'Unassigned')}</strong></p></article>`}).join('')||'<div class="empty-state"><h3>No classes</h3><p>Create a class from a ready book.</p></div>'}</div>`;$('newAdminClass').onclick=()=>openAdminClass()}
function adminTeachers(){const teachers=adminUsers('teacher'),cls=getDB().classes;title('System Admin','Teachers');$('content').innerHTML=`<div class="role-page-head"><div><span class="role-kicker">Staff</span><h1>Teachers</h1><p>Create teacher accounts and see assigned classes.</p></div><button class="primary-btn" id="newAdminTeacher">+ Create teacher</button></div><div class="card clean-list">${teachers.map(t=>{const names=cls.filter(c=>c.teacher_id===t.id).map(c=>c.name);return `<div class="management-row"><div class="student-cell"><div class="avatar">${escapeHtml(t.name[0])}</div><div><strong>${escapeHtml(t.name)}</strong><small>@${escapeHtml(t.username)}</small></div></div><div class="management-row-meta"><span>${escapeHtml(names.join(', ')||'No class assigned')}</span><button class="ghost-btn" data-admin-reset="${t.id}">Reset password</button></div></div>`}).join('')||'<div class="empty-state"><h3>No teachers</h3><p>Create the first teacher account.</p></div>'}</div>`;$('newAdminTeacher').onclick=openAdminTeacher;document.querySelectorAll('[data-admin-reset]').forEach(b=>b.onclick=()=>adminResetPassword(b.dataset.adminReset))}
function adminStudents(){const students=adminUsers('student'),cls=getDB().classes;title('System Admin','Students');$('content').innerHTML=`<div class="role-page-head"><div><span class="role-kicker">Initial enrollment</span><h1>Students</h1><p>Add initial students. Teachers can add future students to their own classes.</p></div><button class="primary-btn" id="newAdminStudent">+ Add student</button></div><div class="card table-wrap clean-table"><table class="data-table"><thead><tr><th>Student</th><th>Class</th><th></th></tr></thead><tbody>${students.map(s=>`<tr><td><div class="student-cell"><div class="avatar">${escapeHtml(s.name[0])}</div><div><strong>${escapeHtml(s.name)}</strong><small>@${escapeHtml(s.username)}</small></div></div></td><td>${escapeHtml(cls.find(c=>s.classIds?.includes(c.id))?.name||'—')}</td><td><button class="ghost-btn" data-admin-reset="${s.id}">Reset password</button></td></tr>`).join('')}</tbody></table></div>`;$('newAdminStudent').onclick=openAdminStudent;document.querySelectorAll('[data-admin-reset]').forEach(b=>b.onclick=()=>adminResetPassword(b.dataset.adminReset))}
function openAdminTeacher(){showModal(`<div class="section-head"><div><span class="role-kicker">Teacher account</span><h3>Create teacher</h3></div><button class="icon-btn" data-close>×</button></div><form id="adminTeacherForm" class="form-grid"><label>Teacher name<input id="adminTeacherName" required></label><label>Username<input id="adminTeacherUsername" required placeholder="e.g. teacher.ahmed"></label><button class="primary-btn" type="submit">Create teacher</button></form><div id="adminCreateResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('adminTeacherForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/admin/teachers',{method:'POST',body:JSON.stringify({name:$('adminTeacherName').value.trim(),username:$('adminTeacherUsername').value.trim()})});await refreshState();$('adminCreateResult').innerHTML=credentialResult('Teacher',r)}catch(err){$('adminCreateResult').innerHTML=`<div class="feedback bad">${escapeHtml(err.message)}</div>`}}}
function openAdminClass(prefillBookId=''){const teachers=adminUsers('teacher'),books=(getDB().books||[]).filter(b=>['ready','pilot'].includes(b.status)&&BOOK_PACKS[b.id]);if(!teachers.length){showModal(`<div class="section-head"><div><span class="role-kicker">Create class</span><h3>Create a teacher first</h3><p class="muted">A class needs an assigned teacher.</p></div><button class="icon-btn" data-close>×</button></div><button class="primary-btn" id="goCreateTeacher">Create teacher</button>`);document.querySelector('[data-close]').onclick=closeModal;$('goCreateTeacher').onclick=openAdminTeacher;return}if(!books.length){showModal(`<div class="section-head"><div><span class="role-kicker">Create class</span><h3>No ready book</h3><p class="muted">A class must be connected to a ready curriculum book.</p></div><button class="icon-btn" data-close>×</button></div>`);document.querySelector('[data-close]').onclick=closeModal;return}const selected=books.some(b=>b.id===prefillBookId)?prefillBookId:books[0].id;showModal(`<div class="section-head"><div><span class="role-kicker">Class setup</span><h3>Create class</h3><p class="muted">Choose the book. The level comes from the book automatically.</p></div><button class="icon-btn" data-close>×</button></div><form id="adminClassForm" class="form-grid"><label>Class name<input id="adminClassName" required placeholder="e.g. A2-B1 Evening"></label><label>Book<select id="adminClassBook">${books.map(b=>`<option value="${b.id}" ${b.id===selected?'selected':''}>${escapeHtml(b.title)} · ${escapeHtml(b.level)}</option>`).join('')}</select></label><label>Teacher<select id="adminClassTeacher">${teachers.map(t=>`<option value="${t.id}">${escapeHtml(t.name)}</option>`).join('')}</select></label><button class="primary-btn" type="submit">Create class</button></form><div id="adminCreateResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('adminClassForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/classes',{method:'POST',body:JSON.stringify({name:$('adminClassName').value.trim(),bookId:$('adminClassBook').value,teacherId:$('adminClassTeacher').value})});await refreshState();closeModal();currentPage='admin-classes';renderNav();adminClasses()}catch(err){$('adminCreateResult').innerHTML=`<div class="feedback bad">${escapeHtml(err.message)}</div>`}}}
function openAdminStudent(){const cls=getDB().classes;if(!cls.length){showModal(`<div class="section-head"><div><span class="role-kicker">Add student</span><h3>Create a class first</h3><p class="muted">Students must belong to a class.</p></div><button class="icon-btn" data-close>×</button></div>`);document.querySelector('[data-close]').onclick=closeModal;return}showModal(`<div class="section-head"><div><span class="role-kicker">Student account</span><h3>Add initial student</h3></div><button class="icon-btn" data-close>×</button></div><form id="adminStudentForm" class="form-grid"><label>Student name<input id="adminStudentName" required></label><label>Username<input id="adminStudentUsername" required placeholder="e.g. amina.ali"></label><label>Class<select id="adminStudentClass">${cls.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}</select></label><button class="primary-btn" type="submit">Create student</button></form><div id="adminCreateResult"></div>`);document.querySelector('[data-close]').onclick=closeModal;$('adminStudentForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/admin/students',{method:'POST',body:JSON.stringify({name:$('adminStudentName').value.trim(),username:$('adminStudentUsername').value.trim(),classId:$('adminStudentClass').value})});await refreshState();$('adminCreateResult').innerHTML=credentialResult('Student',r)}catch(err){$('adminCreateResult').innerHTML=`<div class="feedback bad">${escapeHtml(err.message)}</div>`}}}
function credentialResult(label,r){return `<div class="credential-card"><span>${label} created</span><strong>@${escapeHtml(r.username)}</strong><code>${escapeHtml(r.temporaryPassword)}</code><small>Copy this temporary password now. It will not be shown again.</small></div>`}
async function adminResetPassword(id){try{const r=await api(`/api/admin/users/${id}/reset-password`,{method:'POST'});showModal(`<div class="section-head"><div><span class="role-kicker">Password reset</span><h3>New temporary password</h3></div><button class="icon-btn" data-close>×</button></div><div class="credential-card"><code>${escapeHtml(r.temporaryPassword)}</code><small>Copy and share it privately.</small></div>`);document.querySelector('[data-close]').onclick=closeModal}catch(e){alert(e.message)}}

function showModal(html){let m=$('modalRoot');if(!m){m=document.createElement('div');m.id='modalRoot';document.body.appendChild(m)}m.innerHTML=`<div class="modal-backdrop"><div class="modal-card">${html}</div></div>`;m.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()}}
function closeModal(){const m=$('modalRoot');if(m)m.innerHTML=''}
function escapeAttr(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;')} function escapeHtml(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
